    "explain": "ไข้สมองอักเสบเจอีแบบไม่รุนแรงมีเพียงไข้และปวดศีรษะ ส่วนรูปแบบรุนแรงคือสมองอักเสบ มีไข้สูง ปวดศีรษะ คอแข็ง สับสน ชัก และอัมพาตแบบเกร็ง (spastic paralysis) จนถึงหมดสติ อัตราป่วยตายราวร้อยละ 30 และผู้ที่รอดราวร้อยละ 30 ถึง 50 ยังมีความผิดปกติทางระบบประสาทหลงเหลือ เชื้อนำโดยยุงรำคาญ (Culex) มีสุกรและนกเป็นตัวเพิ่มจำนวนเชื้อ ส่วนคนและม้าเป็นโฮสต์ปลายทาง\n\n❌ ทำไมข้ออื่นผิด\n— ตัวเหลืองตาเหลืองและปัสสาวะสีเข้มเป็นอาการของไข้เหลืองในผู้ป่วยส่วนน้อย\n— เกล็ดเลือดต่ำร่วมกับเม็ดเลือดขาวต่ำเป็นลักษณะเด่นของ SFTS ซึ่งมีเห็บเป็นพาหะ\n— จอประสาทตาอักเสบจนตามัวเป็นรูปแบบรุนแรงทางตาของ Rift Valley fever\n— ไข้ร่วมกับปวดข้อรุนแรงหลายข้อและผื่นเป็นภาพของไข้ชิคุนกุนยา ไม่ใช่สมองอักเสบ\n\n💡 เจอีรุนแรงคือสมองอักเสบ ชัก และอัมพาตแบบเกร็ง",
    "source": "Zoonosis Mid 86(1).pdf หน้า 6",
