    "answer": 2,
    "explain": "ไวรัสไข้หวัดนกเป็นไวรัสไข้หวัดใหญ่สายพันธุ์ A ใน family Orthomyxoviridae มีสารพันธุกรรมเป็น RNA แบบท่อน 8 ท่อน บนผิวไวรัสมีโปรตีนสำคัญสองชนิด คือ hemagglutinin (HA) ซึ่งจับกับรีเซปเตอร์บนผิวเซลล์โฮสต์แล้วพาไวรัสเข้าเซลล์ และ neuraminidase (NA) ซึ่งเป็นเอนไซม์ที่ปลดปล่อยไวรัสรุ่นใหม่ออกจากเซลล์หลังเพิ่มจำนวนเสร็จ โปรตีนทั้งสองมีความหลากหลายสูง จึงใช้ตั้งชื่อ subtype ของ influenza A เช่น H5N1 และ H7N9 โดยนกน้ำเป็นแหล่งรังโรคที่พบได้เกือบทุก subtype\n\n❌ ทำไมข้ออื่นผิด\n— influenza B หมุนเวียนในคนและอยู่ในวัคซีนไข้หวัดใหญ่ตามฤดูกาล ไม่ใช่ไวรัสไข้หวัดนก และไม่ได้แบ่ง subtype ด้วย H และ N\n— หน้าที่สลับกัน HA เป็นตัวจับรีเซปเตอร์ ส่วน NA เป็นตัวปลดปล่อยไวรัส\n— HA และ NA เป็นโปรตีนบนผิวไวรัส จึงเป็นเป้าของแอนติบอดีและเปลี่ยนแปลงอยู่เสมอ\n— HA ไม่ได้คัดลอกจีโนม และ NA ไม่ได้ทำให้ไวรัสทนกรด\n\n💡 HA ใช้เข้าเซลล์ NA ใช้ออกจากเซลล์",
