    "explain": "ไวรัสสัตว์ปีกชอบจับรีเซปเตอร์ sialic acid แบบ alpha 2,3 ส่วนไวรัสของสัตว์เลี้ยงลูกด้วยนมชอบแบบ alpha 2,6 การติดข้ามระหว่างสองกลุ่มจึงเกิดได้ยาก แต่ไวรัสไข้หวัดใหญ่เป็น RNA ไวรัสที่ไม่มีเอนไซม์ตรวจแก้การคัดลอก จึงเกิด point mutation ในอัตราสูง ถ้าการกลายพันธุ์ตกที่ตำแหน่งจับรีเซปเตอร์บน HA เพียงราว 2 ตำแหน่ง ไวรัสสัตว์ปีกก็จับรีเซปเตอร์ของสัตว์เลี้ยงลูกด้วยนมได้และข้ามสปีชีส์ได้ กลไกนี้เป็นการสะสม mutation แบบ antigenic drift ร่วมกับการปรับตัวเข้ากับโฮสต์ ไม่ใช่ antigenic shift ที่สลับท่อนยีนระหว่างไวรัสจนเกิด subtype ใหม่\n\n❌ ทำไมข้ออื่นผิด\n— NA ทำหน้าที่ปลดปล่อยไวรัสออกจากเซลล์ ไม่ได้กำหนดว่าไวรัสจับรีเซปเตอร์ชนิดใด\n— การกลายพันธุ์ที่ cleavage site ของ HA ทำให้ LPAI สาย H5 หรือ H7 กลายเป็น HPAI คือเพิ่มความรุนแรงในสัตว์ปีก ไม่ได้เปลี่ยนรีเซปเตอร์ที่จับ\n— จีโนมของ influenza A มี 8 ท่อนเสมอ การข้ามสปีชีส์ไม่ได้เกิดจากการเพิ่มจำนวนท่อน\n— ไวรัสไม่ได้สร้างเปลือกหุ้มใหม่เพื่อข้ามสปีชีส์ ตัวกำหนดคือการจับรีเซปเตอร์ของ HA\n\n💡 จะข้ามสปีชีส์ได้ต้องเปลี่ยนที่ HA ตรงจุดจับรีเซปเตอร์",
