    "answer": 3,
    "explain": "บรรพบุรุษของไวรัส HPAI H5N1 สายนี้คือไวรัสที่แยกได้จากห่านในมณฑลกวางตุ้งปี 1996 ซึ่งเรียกว่า A/Goose/Guangdong/1/1996 พบในแหล่งนกน้ำที่มีเป็ด ไก่ และปศุสัตว์อยู่รอบ ๆ ปีถัดมาคือ 1997 เชื้อไปถึงตลาดค้าสัตว์ปีกมีชีวิตในฮ่องกงและเริ่มติดคน จนฮ่องกงต้องทำลายไก่ราว 1.25 ล้านตัวเพื่อหยุดการแพร่ จากนั้นปี 2004 เชื้อกระจายไปทั่วเอเชีย ยุโรป และแอฟริกาตามเส้นทางบินของนกอพยพ และประเทศไทยก็พบการระบาดครั้งแรกในปีนั้น ส่วนลำดับเหตุการณ์ของ WHO บันทึกว่าเชื้อไปถึงยุโรปปลายปี 2005 และถึงแอฟริกาในปี 2006\n\n❌ ทำไมข้ออื่นผิด\n— ตลาดค้าสัตว์ปีกในฮ่องกงปี 1997 คือจุดที่ H5N1 เริ่มติดคน หลังพบบรรพบุรุษในกวางตุ้งแล้วหนึ่งปี\n— ปี 2004 คือปีที่ H5N1 เข้ามาระบาดในไทย ส่วนเป็ดไล่ทุ่งเป็นแหล่งรังโรคที่ช่วยกระจายเชื้อภายในประเทศ\n— โคนมในสหรัฐอเมริกาปี 2024 ติด H5N1 clade 2.3.4.4b ซึ่งเป็นลูกหลานรุ่นหลังของสายนี้\n— สุกรกับเม็กซิโกปี 2009 เป็นเรื่องของ pandemic H1N1 ซึ่งมีต้นตอจากไวรัสในสุกร ไม่ใช่ H5N1\n\n💡 H5N1 เริ่มจากห่านกวางตุ้ง 1996 แล้วเข้าคนที่ฮ่องกง 1997",
