    "q": "แหล่งอาหารใดต่อไปนี้มีโอกาสพบเชื้อ Toxoplasma gondii ได้\n1. เนื้อหมูจากฟาร์มสุกรเลี้ยงแบบระบบเปิดที่ไม่ได้ผ่านการรับรองมาตรฐานฟาร์ม\n2. ผักจากสวนที่มักพบแมวจรมาขับถ่าย\n3. นมแพะสดที่ยังไม่ผ่านการต้ม\n4. เนื้อแพะจากฟาร์มที่เลี้ยงร่วมกับแมว",
