    "explain": "Toxoplasma gondii มีระยะติดต่อสามแบบ แหล่งอาหารทั้งสี่จึงมีโอกาสพบเชื้อได้ทั้งหมด เนื้อหมูและเนื้อแพะอาจมี tissue cyst ที่มี bradyzoite อยู่ในกล้ามเนื้อ เพราะสุกรและสัตว์เคี้ยวเอื้องขนาดเล็กมักมี tissue cyst โดยเฉพาะเมื่อเลี้ยงแบบเปิดหรือเลี้ยงร่วมกับแมวซึ่งเป็นโฮสต์แท้ ผักจากสวนที่แมวมาขับถ่ายปนเปื้อน oocyst ที่ sporulate แล้วในสิ่งแวดล้อม และนมแพะดิบที่ไม่ผ่านความร้อนอาจมี tachyzoite ปนอยู่ การป้องกันจึงต้องทำให้เนื้อสุกทั่วถึง ล้างผักให้สะอาด และต้มหรือพาสเจอร์ไรซ์นมก่อนดื่ม\n\n❌ ทำไมข้ออื่นผิด\n— ผักที่ปนเปื้อนอุจจาระแมวเป็นเพียงทางหนึ่ง เนื้อสัตว์ที่มี tissue cyst และนมแพะดิบก็เป็นแหล่งเชื้อด้วย\n— เนื้อหมูและเนื้อแพะมี tissue cyst ได้จริง แต่ยังขาดผักที่ปนเปื้อน oocyst และนมแพะดิบ\n— ผักและนมแพะดิบเป็นแหล่งเชื้อจริง แต่ยังขาดเนื้อหมูและเนื้อแพะที่มี tissue cyst\n— ยังขาดนมแพะสดที่ไม่ผ่านการต้ม ซึ่งอาจมี tachyzoite ปนอยู่\n\n💡 Toxoplasma มาได้ทั้งจากเนื้อ ผัก และนมดิบ ตามระยะติดต่อสามแบบของเชื้อ",
