    "answer": 0,
    "explain": "Giardia แบ่งตามการตรวจทางโมเลกุลเป็น assemblage A ถึง G กลุ่มที่ติดคนและติดข้ามระหว่างสัตว์กับคนได้คือ assemblage A และ B ซึ่งพบได้ทั้งในคน สุนัข แมว และสัตว์เลี้ยงลูกด้วยนมอื่น ส่วน assemblage C และ D จำเพาะกับสุนัข และ F จำเพาะกับแมว สุนัขหรือแมวที่ตรวจพบ Giardia จึงอาจมีหรือไม่มีเชื้อชนิดที่ติดคนก็ได้ และชุดตรวจทั่วไปบอก assemblage ไม่ได้ การตัดสินใจรักษาสัตว์ที่ไม่มีอาการจึงพิจารณาจากคนในบ้าน เช่น มีเด็กเล็ก ผู้ป่วยมะเร็ง หรือผู้มีภูมิคุ้มกันต่ำหรือไม่\n\n❌ ทำไมข้ออื่นผิด\n— C และ D เป็น assemblage ที่จำเพาะกับสุนัข ไม่ติดคน\n— A ติดคนได้ แต่ F เป็น assemblage ที่จำเพาะกับแมว\n— B ติดคนได้ แต่ C เป็น assemblage ของสุนัข\n— D เป็นของสุนัขและ F เป็นของแมว ทั้งสองไม่ติดคน\n\n💡 Giardia ที่ติดคนคือ A กับ B ส่วน C กับ D เป็นของสุนัข และ F เป็นของแมว",
