    "answer": 1,
    "explain": "leishmaniasis ที่ติดภายในประเทศไทยส่วนใหญ่เกิดจาก Leishmania martiniquensis และ L. orientalis เดิมสงสัยริ้นฝอยทรายหลายชนิดเป็นพาหะ เช่น Sergentomyia gemmea และ S. barraudi ต่อมามีการตรวจพบดีเอ็นเอของเชื้อทั้งสองชนิดในริ้น Culicoides หลายชนิดที่จับได้ในพื้นที่ที่มีผู้ป่วยทั้งภาคเหนือและภาคใต้ และพบว่าริ้นบางชนิดกินเลือดคน ริ้น Culicoides จึงเป็นพาหะที่น่าสงสัยอีกกลุ่ม ริ้นตัวเล็กกว่ายุงมากจนลอดมุ้งธรรมดาได้และควบคุมยาก การป้องกันจึงเน้นทายากันแมลง สวมเสื้อผ้าปกคลุมมิดชิด และเลี่ยงกิจกรรมกลางแจ้งช่วงพลบค่ำ\n\n❌ ทำไมข้ออื่นผิด\n— ริ้นดำ (Simulium) เป็นพาหะของโปรโตซัว Leucocytozoon ในสัตว์ปีก ไม่ใช่พาหะของ Leishmania\n— แมลงวันคอกสัตว์เป็นแมลงกัดที่ถ่ายทอด Trypanosoma evansi ซึ่งก่อโรค surra ในปศุสัตว์\n— มวนเพชฌฆาตเป็นพาหะของ Trypanosoma cruzi ที่ก่อโรค Chagas ในทวีปอเมริกา\n— หมัดแมวเป็นพาหะของ Rickettsia felis และเป็นโฮสต์กลางของพยาธิตืด Dipylidium caninum\n\n💡 เชื้อ Leishmania ในไทยตรวจพบได้ทั้งในริ้นฝอยทรายและริ้น Culicoides ที่ตัวเล็กจนลอดมุ้ง",
    "source": "Zoonosis Mid 86(1).pdf หน้า 27",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf น.27 ใต้ Question 13 ภาพหน้าจอข้อสอบออนไลน์ Vet 85 (ข้อใดผิดในการป้องกัน Leishmania) โน้ตลายมือใต้ภาพวงจร Transmission: bites of infected female phlebotomine sandflies ว่า แต่ปจบ. เจอใน Culicoides ด้วย -> ตัวเล็กกว่ายุง ควบคุมยาก วงรอบด้วยสีฟ้าและขีดเส้นหยักแดงใต้ ตัวเล็กกว่ายุง และ ควบคุมยาก; แหล่งปี 2026 และบันทึกในคลังไม่ได้พูดถึง Culicoides จึงตรวจกับวรรณกรรมผ่าน PubMed: Promrangsee et al. 2024 Parasit Vectors 17:400 doi 10.1186/s13071-024-06487-z (ตรวจพบ L. martiniquensis และ L. orientalis ใน Culicoides อย่างน้อย 11 ชนิดที่ลำปาง และพบการกินเลือดคน สรุปว่าเป็น putative vectors), Ampol et al. 2024 Insects 15:327 doi 10.3390/insects15050327 (เชียงราย) และ Tepboonrueng et al. 2025 Parasit Vectors 18:194 doi 10.1186/s13071-025-06812-0 (ภาคใต้); ริ้นฝอยทรายที่สงสัยในไทยตรวจกับ notes-y2-parasit-1 Lect 7 Part 2 (Sergentomyia gemmea, S. barraudi, Phlebotomus argentipes) และการป้องกันตรวจกับ notes-85-zoonoses zoo-protozoal (sandfly ลอดมุ้ง) กับ 106133; ตัวลวงตรวจกับ Gf54Vsock7s (2025) (T. evansi จาก biting flies, T. cruzi จาก kissing bug) notes-y2-parasit-1 หัวข้อ Leucocytozoon (L. simondi มี Simulium sp. เป็นพาหะ; ตัวลวงนี้แทนยุงลาย เพราะวลี ตัวเล็กกว่ายุง ในโจทย์ตัดยุงออกเอง และ ริ้น Culicoides เคยเป็นตัวเลือกเดียวที่ขึ้นต้นด้วยคำว่า ริ้น เหมือนริ้นฝอยทรายในโจทย์) และคลัง rickettsial กับ Dipylidium; 208009 และ 106133 ทดสอบเฉพาะริ้นฝอยทราย",
