    "answer": 2,
    "explain": "Cryptosporidium ก่อโรคท้องเสียเป็นน้ำ (watery diarrhea) ร่วมกับปวดท้อง ในคนที่ภูมิคุ้มกันปกติมักหายได้เอง แต่ในผู้ติดเชื้อ HIV หรือผู้มีภูมิคุ้มกันบกพร่องจะท้องเสียเรื้อรังรุนแรงจนเป็นอันตราย โรคนี้ติดผ่านน้ำ (waterborne) เป็นหลัก เพราะ oocyst ที่ขับออกมากับอุจจาระติดต่อได้ทันทีและทนคลอรีน จึงพบการระบาดจากสระว่ายน้ำและสวนน้ำ ส่วนสัตวแพทย์และผู้ดูแลลูกโคที่ท้องเสียเป็นกลุ่มเสี่ยงจากการสัมผัสอุจจาระ\n\n❌ ทำไมข้ออื่นผิด\n— ถ่ายเป็นมูกเลือด ปวดเบ่ง และฝีในตับเป็นภาพของ amoebiasis จาก Entamoeba histolytica\n— ไข้ร่วมกับเม็ดเลือดแดงแตกเป็นลักษณะของ babesiosis ที่มีเห็บเป็นพาหะ\n— ต่อมน้ำเหลืองโตเล็กน้อยหรือไม่มีอาการเป็นภาพของ toxoplasmosis ในคนที่ภูมิคุ้มกันปกติ\n— ตุ่มแผลเรื้อรังตรงที่แมลงกัดเป็นรูปแบบทางผิวหนังของ leishmaniasis จากริ้นฝอยทราย\n\n💡 Cryptosporidium คือท้องเสียเป็นน้ำที่มากับน้ำ และรุนแรงในผู้ติดเชื้อ HIV",
    "source": "Zoonosis Mid 86(1).pdf หน้า 16",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf น.16 ภาพสไลด์ CRYPTOSPORIDIOSIS ใต้ Question 2 (เชื้อใดมักพบผู้ป่วยมีประวัติไปสวนน้ำหรือสระว่ายน้ำสาธารณะ) ขีดเส้นใต้แดงที่ CRYPTOSPORIDIOSIS ไฮไลต์ watery diarrhea พร้อมลายมือ ปวดท้อง ถ่ายเหลว และดาวกับวงแดงที่ Waterborne disease; ตรวจกับ Gf54Vsock7s (2025) หัวข้อ Cryptosporidiosis (watery diarrhea, self-limiting ในคนภูมิคุ้มกันปกติ, severe in AIDS, resistant to chlorine, calf diarrhea handlers) notes-85-zoonoses zoo-protozoal (Cryptosporidium ติดต่อได้ทันทีหลังขับออก, opportunistic pathogen ใน HIV) และ notes-y2-parasit-1 (การระบาดจากสระว่ายน้ำและทะเลสาบ); ตัวลวงตรวจกับ Gf54Vsock7s (babesiosis hemolytic disease จากเห็บ, leishmaniasis รูปแบบผิวหนัง, amebiasis) และ notes-y2-parasit-1 Lect 9.1 (Toxoplasma ในคนภูมิคุ้มกันปกติไม่มีอาการหรือต่อมน้ำเหลืองโต); 106126 ให้อาการท้องเสียไว้ในโจทย์ ไม่มีข้อใดคีย์ลักษณะอาการของ cryptosporidiosis; ไม่มีคลิปบรรยาย protozoa ปี 2026 ในคลัง",
