    "answer": 1,
    "explain": "Oxyspirura mansoni เป็นพยาธินัยน์ตาของไก่และนกหลายชนิด ตัวเต็มวัยอาศัยใต้หนังตาที่สามและในถุงเยื่อบุตาของไก่ และมีแมลงสาบเป็นโฮสต์กลาง ในคน ตัวอ่อนของพยาธิชนิดนี้ไชอยู่ใต้ผิวหนังเกิดเป็น cutaneous larva migrans คือรอยนูนแดงคดเคี้ยวที่เลื่อนไปตามทางที่ตัวอ่อนไช รายงานกลุ่มผู้ป่วยในเวียดนามปี 2020 พบตัวอ่อนพยาธินัยน์ตาสัตว์ปีกจากรอยโรค และปี 2025 ยืนยันด้วยรูปร่างและลำดับพันธุกรรมว่าตัวอ่อนจากผู้ป่วยตรงกับ O. mansoni ตัวเต็มวัยจากไก่ที่ครอบครัวผู้ป่วยเลี้ยงไว้ นับเป็นครั้งแรกที่ยืนยันว่าพยาธิจากสัตว์ปีกก่อ larva migrans ในคน ขณะที่เชื้อที่ยืนยันก่อนหน้านี้ล้วนมาจากสัตว์เลี้ยงลูกด้วยนม เช่น พยาธิปากขอของสุนัขและแมว\n\n❌ ทำไมข้ออื่นผิด\n— ตุ่มหนองกระจายเป็นผื่นจากการติดเชื้อหรือการอักเสบของรูขุมขน ไม่ใช่รอยทางของตัวอ่อนที่ไช\n— ก้อนแดงกดเจ็บที่หน้าแข้งเป็นการอักเสบของไขมันใต้ผิวหนังจากปฏิกิริยาภูมิคุ้มกัน และไม่เลื่อนที่\n— ผื่นลมพิษขึ้นแล้วยุบภายในไม่กี่ชั่วโมง ไม่ได้เป็นทางคดเคี้ยวที่ค่อย ๆ เลื่อนไป\n— ก้อนเนื้อแข็งในชั้นผิวหนังเป็นเนื้องอกชนิดไม่ร้ายของเนื้อเยื่อเส้นใย ไม่เกี่ยวกับพยาธิ\n\n💡 ตัวอ่อนพยาธิที่ไชใต้ผิวหนังเห็นเป็นรอยทางคดเคี้ยว ไม่ว่าจะมาจากสุนัขหรือไก่",
    "source": "Zoonosis mid TJ เฉลย.pdf หน้า 27",
    "sourceType": "student-compilation",
    "verified": "Zoonosis mid TJ เฉลย.pdf น.27 ข้อ 19 (คำตอบ ข. Cutaneous larva migrans ตัวเลือกห้าข้อ Pustular rash, Cutaneous larva migrans, Erythema nodosum, Urticaria, Dermatofibroma; หัวบล็อก Parasitic zoonoses (Helminth) ไม่ได้ระบุที่มา ข้อ 1-19 เป็นชุดเดียวกับบันทึกหลังสอบ Vet 85) ซึ่งเป็นหน้าเดียวกับ Zoonosis Mid 86(1).pdf น.63; ถามซ้ำใน Zoonosis Mid 86(1).pdf น.30 ข้อ 19 (= Zoonosis Mid 86.pdf น.13; ล่าสุดมีเคสคนติดพยาธินัยน์ตาไก่ (Oxyspirura manaoni) -> cutaneous larva migrans ไฮไลต์เขียว ในหน้าที่มุมขวาบนจดว่า ตรง แต่ข้อท้าย ๆ ไม่แน่ใจคำตอบ); แหล่งปี 2026 ไม่ได้พูดถึง Oxyspirura จึงตรวจกับวรรณกรรมผ่าน PubMed: Doanh et al. 2025 Parasitol Res 124:46 doi 10.1007/s00436-025-08473-5 (First confirmation of the chicken eyeworm, Oxyspirura mansoni, as a causative pathogen of human cutaneous larva migrans: case series เวียดนาม 2020, 18S rDNA ITS2 cox1 ของตัวอ่อนจากผู้ป่วยตรงกับตัวเต็มวัยจากไก่ของครอบครัว, สกุลนี้ใช้แมลงสาบ ตั๊กแตน จิ้งหรีดเป็นโฮสต์กลาง) และตำแหน่งตัวเต็มวัยใต้หนังตาที่สามตรวจกับ questions-vca (avian eyeworm) ; 202348 ถามเฉพาะชื่อพยาธิ ไม่มีข้อใดคีย์อาการทางผิวหนัง",
