    "answer": 2,
    "explain": "พยาธิปากขอที่พบเป็นหลักในสุนัขและแมวของไทยคือ Ancylostoma ceylanicum ส่วนชนิดอื่นพบได้น้อยกว่า ไข่ของพยาธิปากขอทุกชนิดหน้าตาเหมือนกันและใช้ยาถ่ายพยาธิแบบเดียวกัน จึงแยกชนิดจากไข่ไม่ได้ ความสำคัญทางสาธารณสุขของ A. ceylanicum คือติดได้ทั้งสุนัข แมว และคน และในคนเจริญเป็นตัวเต็มวัยครบวงจรในลำไส้จนออกไข่ได้ คนติดจากตัวอ่อนระยะ L3 ในดินที่ไชผ่านผิวหนังเป็นหลัก หรือจากการกิน\n\n❌ ทำไมข้ออื่นผิด\n— Ancylostoma caninum พบในสุนัขของไทยได้เช่นกัน แต่ในคนตัวอ่อนมักไชอยู่ใต้ผิวหนังเกิด creeping eruption\n— Necator americanus เป็นพยาธิปากขอของคน ไม่ได้มีสุนัขและแมวเป็นโฮสต์\n— Ancylostoma duodenale เป็นพยาธิปากขอของคน ไม่ใช่พยาธิของสุนัขและแมว\n— Strongyloides stercoralis เป็นพยาธิเส้นด้าย ตัวอ่อนไชผิวหนังได้ แต่ไม่ใช่พยาธิปากขอ\n\n💡 ปากขอในสุนัขและแมวของไทยส่วนใหญ่คือ ceylanicum ซึ่งโตครบวงจรในคนได้",
