    "answer": 0,
    "explain": "ตัวเต็มวัยของพยาธิปากขออยู่ในลำไส้เล็กท่ามกลางเอนไซม์ย่อยอาหารของโฮสต์และเม็ดเลือดขาวที่เข้ามากำจัดมัน ที่ผิวของตัวพยาธิมี proteinase inhibitor ซึ่งยับยั้ง chymotrypsin และ elastase จากตับอ่อน รวมถึง elastase ของ neutrophil ตัวพยาธิจึงไม่ถูกย่อยหรือทำลาย เมื่อรวมกับสารกันเลือดแข็งที่ใช้ขณะดูดเลือด พยาธิปากขอจึงปิดทุกทางที่โฮสต์ใช้กำจัดมัน ยกเว้นยาถ่ายพยาธิ ซึ่งยังรักษาได้ผลทุกราย โฮสต์จึงเสียเลือดเรื้อรังจนโลหิตจางแบบขาดธาตุเหล็ก\n\n❌ ทำไมข้ออื่นผิด\n— protease และ hyaluronidase เป็นเอนไซม์ของตัวอ่อนระยะ L3 ที่ใช้ไชผิวหนัง ไม่ใช่หน้าที่ของ proteinase inhibitor\n— การยับยั้ง factor VII และ X เป็นหน้าที่ของ anticoagulant peptide\n— การยับยั้งการรวมตัวของเกล็ดเลือดเป็นหน้าที่ของ hookworm platelet inhibitor\n— พยาธิปากขอยังแพ้ยาถ่ายพยาธิ ตรวจพบแล้วถ่ายพยาธิก็หายได้\n\n💡 inhibitor ที่ผิวมีไว้กันตัวพยาธิไม่ให้ถูกย่อย ส่วนสารกันเลือดแข็งมีไว้กินเลือด",
