    "explain": "ลูกสุนัขติดพยาธิปากขอจากแม่ทางน้ำนม และติดพยาธิไส้เดือนจากแม่ผ่านรกเป็นหลัก การถ่ายพยาธิครั้งแรกตอนอายุ 2 เดือนจึงมุ่งจัดการพยาธิปากขอและพยาธิไส้เดือนที่ได้จากแม่ ครั้งที่สองตอน 2 เดือนครึ่งเก็บพยาธิปากขอที่เหลือ ครั้งที่สามตอน 3 เดือนจัดการพยาธิแส้ม้าและพยาธิไส้เดือน พร้อมเริ่มป้องกันพยาธิหัวใจ และครั้งที่สี่ตอน 6 เดือนเก็บพยาธิแส้ม้าอีกรอบ เพราะพยาธิแส้ม้าใช้เวลาราว 3 เดือนตั้งแต่ติดจนออกไข่ จึงต้องถ่ายซ้ำให้ทันรอบของมัน\n\n❌ ทำไมข้ออื่นผิด\n— ลำดับที่ถ่ายแส้ม้าตั้งแต่ครั้งที่สองแล้วปิดท้ายด้วยไส้เดือน ไม่ตรงกับรอบของพยาธิ แส้ม้าต้องจัดการตอน 3 และ 6 เดือน\n— ลูกสุนัขไม่ได้รับพยาธิแส้ม้าจากแม่ ครั้งแรกจึงต้องเริ่มที่พยาธิปากขอกับพยาธิไส้เดือน\n— การป้องกันพยาธิหัวใจเริ่มตอนอายุราว 3 เดือน ไม่ใช่ตั้งแต่ครั้งแรก\n— ครั้งแรกต้องครอบคลุมทั้งปากขอและไส้เดือนที่ได้จากแม่ และแส้ม้าไม่ได้ถูกจัดการตั้งแต่ครั้งที่สอง\n\n💡 เริ่มจากพยาธิที่ได้จากแม่ แล้วปิดท้ายด้วยแส้ม้าที่วงจรยาว 3 เดือน",
