      "สมุดวัคซีนของคลินิกเพียงเล่มเดียว ซึ่งถือว่าครบตามกฎหมายแล้ว",
      "ใบอนุญาตเคลื่อนย้ายสัตว์ออกนอกเขตโรคระบาดสัตว์ชั่วคราว",
