      "เหรียญเครื่องหมายประจำตัวสัตว์สีตามปี และใบรับรองการฉีดวัคซีน",
      "ใบรับรองว่าเจ้าของสัตว์ได้รับวัคซีนป้องกันล่วงหน้าแล้ว"
