    "answer": 3,
    "explain": "พระราชบัญญัติโรคพิษสุนัขบ้ากำหนดให้สัตวแพทย์ที่ฉีดวัคซีนมอบเหรียญเครื่องหมายประจำตัวสัตว์ที่แสดงว่าฉีดวัคซีนแล้ว พร้อมใบรับรองการฉีดวัคซีน (ใบเหลือง) ให้เจ้าของ เหรียญมีสามสีคือแดง เขียว และน้ำเงิน วนตามปี เช่น ปี 2569 สีเขียว ปี 2570 สีน้ำเงิน และปี 2571 กลับมาเป็นสีแดง สัตวแพทย์ที่ไม่มอบสิ่งที่กฎหมายกำหนดมีโทษปรับไม่เกิน 200 บาท แม้ในทางปฏิบัติการบังคับใช้ยังไม่เข้มงวด กฎหมายฉบับเดียวกันยังกำหนดให้ฉีดวัคซีนเข็มแรกเมื่อสัตว์อายุ 2 ถึง 4 เดือน และให้อำนาจเจ้าหน้าที่ท้องถิ่นสั่งทำลายสัตว์ไม่มีเจ้าของที่หาเจ้าของไม่ได้\n\n❌ ทำไมข้ออื่นผิด\n— สมุดวัคซีนที่คลินิกนิยมให้ใช้แทนเหรียญและใบรับรองที่กฎหมายกำหนดไม่ได้\n— การควบคุมการเคลื่อนย้ายสัตว์ในเขตโรคระบาดสัตว์ชั่วคราวเป็นอำนาจตามพระราชบัญญัติโรคระบาดสัตว์ ซึ่งเป็นกฎหมายคนละฉบับ\n— ไมโครชิปไม่ใช่สิ่งที่พระราชบัญญัติโรคพิษสุนัขบ้ากำหนดให้มอบหลังฉีดวัคซีน\n— การฉีดวัคซีนป้องกันล่วงหน้าในคนเป็นงานของบุคลากรทางการแพทย์ ไม่ใช่สิ่งที่สัตวแพทย์รับรองให้\n\n💡 ฉีดวัคซีนพิษสุนัขบ้าแล้วต้องได้ทั้งเหรียญสีตามปีและใบเหลือง",
    "source": "Zoonosis Mid 86(1).pdf หน้า 57",
