    "answer": 4,
    "explain": "Anisakis เป็นพยาธิตัวกลมที่ตัวอ่อนระยะ L3 อยู่ในเนื้อปลาทะเลและหมึก คนเป็นโฮสต์โดยบังเอิญเมื่อกินอาหารทะเลดิบหรือปรุงไม่สุก ตัวอ่อนไชฝังที่ผนังกระเพาะอาหารหรือลำไส้ แล้วเกิดการอักเสบที่มี eosinophil จำนวนมากรอบตัวพยาธิ ผนังลำไส้จึงหนาตัว ปวดท้อง ถ่ายเป็นเลือด หรือลำไส้อุดตันได้ อาการเกิดได้ตั้งแต่ทันทีหลังกินจนถึงราว 2 เดือน และมักเลียนแบบโรคอื่น เช่น Crohn's disease ไส้ติ่งอักเสบ หรือเนื้องอก หลายรายรู้สาเหตุหลังผ่าตัดแล้วพบตัวพยาธิ ประวัติการกินปลาดิบจึงเป็นเบาะแสสำคัญ\n\n❌ ทำไมข้ออื่นผิด\n— Gnathostoma ติดจากปลาน้ำจืด กบ หรือสัตว์ปีกที่ปรุงไม่สุก ตัวอ่อนไชไปใต้ผิวหนังเป็นก้อนบวมที่เลื่อนที่ได้ และอาจไปที่สมอง\n— Paragonimus ติดจากปูหรือกุ้งน้ำจืดดิบ ตัวเต็มวัยอยู่ในปอด อาการจึงคล้ายวัณโรคปอด\n— Schistosoma ไม่ได้ติดจากการกินปลา แต่ระยะ cercaria ในน้ำจืดไชผ่านผิวหนัง\n— Capillaria philippinensis ติดจากปลาน้ำจืดตัวเล็กดิบ อาการเด่นคือท้องเสียเรื้อรังและการดูดซึมผิดปกติ ไม่ใช่ก้อนอักเสบที่เลียนแบบ Crohn's disease\n\n💡 ปลาทะเลดิบกับรอยโรคในลำไส้ที่เหมือน Crohn's disease นึกถึง Anisakis",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 15",
