    "q": "ข้อใดต่อไปนี้เป็นระยะติดต่อสู่คน (infective stage) ของพยาธิ Opisthorchis spp.",
    "options": [
      "Cercaria",
      "Metacercaria",
      "Redia",
      "Sporocyst",
      "Embryonated egg"
    ],
    "answer": 1,
    "explain": "Opisthorchis viverrini มีโฮสต์กลาง 2 ตัว ไข่ที่มี miracidium อยู่ข้างในปนลงแหล่งน้ำไปถึงหอยซึ่งเป็นโฮสต์กลางตัวที่ 1 ในหอยพยาธิเจริญผ่านระยะ sporocyst และ redia จนเป็น cercaria ซึ่งออกจากหอยไปไชเข้าปลาเกล็ดขาว (ปลากลุ่ม cyprinid) ที่เป็นโฮสต์กลางตัวที่ 2 แล้วเจริญเป็น metacercaria ในเนื้อปลา คน แมว และสุนัขติดพยาธิเมื่อกินปลาดิบหรือสุกไม่ทั่วที่มี metacercaria ตัวอ่อนจึงไปเจริญเป็นตัวเต็มวัยในท่อน้ำดี การไม่ถ่ายอุจจาระลงแหล่งน้ำช่วยตัดวงจรที่หอย ส่วนการปรุงปลาให้สุกตัดวงจรที่คน\n\n❌ ทำไมข้ออื่นผิด\n— Cercaria เป็นระยะที่ออกจากหอยไปไชปลา คนไม่ได้ติดจากระยะนี้\n— Redia เป็นระยะที่เพิ่มจำนวนอยู่ภายในหอย ไม่ได้ออกมาสู่น้ำหรือปลา\n— Sporocyst เป็นระยะแรกที่เจริญในหอยหลังจาก miracidium เข้าสู่หอย\n— ไข่ที่มีตัวอ่อนเป็นระยะที่ติดหอยซึ่งเป็นโฮสต์กลางตัวที่ 1 คนกลืนไข่เข้าไปจึงไม่ติดพยาธิ\n\n💡 Cercaria ไชปลา ส่วน metacercaria ในปลาดิบคือระยะที่ติดคน",
