    "type": "mcq",
    "examScope": "midterm",
    "q": "การติดพยาธิชนิดใดมีความเสี่ยงต่อการเกิดมะเร็งกระเพาะปัสสาวะ (bladder cancer) มากที่สุด",
    "options": [
      "Paragonimus",
      "Capillaria",
      "Opisthorchis",
      "Schistosoma",
      "Gnathostoma"
    ],
    "answer": 3,
    "explain": "Schistosoma เป็นพยาธิใบไม้เลือด ตัวเต็มวัยอาศัยอยู่ในหลอดเลือดดำ ชนิด S. haematobium อยู่ในกลุ่มหลอดเลือดดำรอบกระเพาะปัสสาวะ ไข่ที่มีหนามแหลมฝังในผนังกระเพาะปัสสาวะและกระตุ้นการอักเสบเรื้อรัง ทำให้ปัสสาวะเป็นเลือด ผนังกระเพาะปัสสาวะเป็นพังผืด ไตเสียหาย และเพิ่มความเสี่ยงมะเร็งกระเพาะปัสสาวะ เรียกว่า urogenital schistosomiasis ส่วนชนิดที่อยู่ในหลอดเลือดดำ mesenteric เช่น S. mansoni และ S. japonicum ทำให้เกิดอาการทางลำไส้ คนติดเมื่อระยะ cercaria ในน้ำจืดไชผ่านผิวหนังขณะลงแช่น้ำ\n\n❌ ทำไมข้ออื่นผิด\n— Paragonimus เป็นพยาธิใบไม้ปอด ทำให้ไอเรื้อรังและไอเป็นเลือดคล้ายวัณโรคปอด\n— Capillaria philippinensis อยู่ในลำไส้เล็ก ทำให้ท้องเสียเรื้อรังและการดูดซึมผิดปกติ\n— Opisthorchis viverrini อยู่ในท่อน้ำดีและสัมพันธ์กับมะเร็งท่อน้ำดี (cholangiocarcinoma) ไม่ใช่มะเร็งกระเพาะปัสสาวะ\n— Gnathostoma เป็นตัวอ่อนที่ไชไปใต้ผิวหนังและอวัยวะต่าง ๆ ไม่ได้อาศัยในหลอดเลือดรอบกระเพาะปัสสาวะ\n\n💡 Opisthorchis คู่กับมะเร็งท่อน้ำดี ส่วน Schistosoma haematobium คู่กับมะเร็งกระเพาะปัสสาวะ",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 16",
