    "verified": "ZOONOSES MID 86 🏅.pdf หน้า 16 Question 3 (ตัวเลือก A. Schistosoma ไฮไลต์ชมพูเป็นปุ่มที่เลือกไว้ พร้อมลายมือสีม่วง Infective stage: Cercaria ข้างตัวเลือก ซึ่งเป็นเรื่องเดียวกับ D1-H9); ซ้ำใน ZOONOSES MID 86 🏅.pdf หน้า 20 ลายมือ Schistosomiasis S. haematobium และ urinary bladder cancer ขีดเส้นใต้ฟ้า; คลิป 2026 gwgmq6oGOWc ไม่ได้สอน Schistosoma และ notes/wiki ของวิชามีเพียงตารางที่จัด Schistosoma เป็นพยาธิที่มากับน้ำ จึงตรวจกับวรรณกรรมผ่าน PubMed: Ponzo et al. 2024 Eur J Microbiol Immunol 14(2):86-96 doi 10.1556/1886.2024.00013 (S. haematobium, S. mansoni, S. japonicum; urogenital symptoms haematuria, bladder fibrosis, kidney damage, increased risk of bladder cancer; cercariae penetrate the skin while bathing); มะเร็งท่อน้ำดีของ OV ตรวจกับ gwgmq6oGOWc [13:41-14:56] และ wiki zoonoses--zoo-helminthic--trematode-2-priority-zoonoses--v1",
