    "explain": "Paragonimus เป็นพยาธิใบไม้ปอด คนติดจากการกินปูหรือกุ้งน้ำจืดดิบหรือดองที่มี metacercaria ตัวอ่อนไชผ่านผนังลำไส้ไปเจริญเป็นตัวเต็มวัยในเนื้อปอด ทำให้ไอเรื้อรัง ไอเป็นเลือด และเจ็บหน้าอก ซึ่งเหมือนวัณโรคปอดมาก ผู้ป่วยที่ไอเรื้อรังและมีประวัติกินปูดิบจึงต้องวินิจฉัยแยกระหว่างพยาธิใบไม้ปอดกับ pulmonary tuberculosis ให้ได้ ในสุนัขตรวจหาไข่ในอุจจาระด้วยวิธี sedimentation รักษาด้วย praziquantel และตัวพยาธิอาจไชผิดที่ไปสมองได้\n\n❌ ทำไมข้ออื่นผิด\n— Meningitis เกิดได้เมื่อพยาธิไชผิดที่ไปสมอง ไม่ใช่ภาพของการติดที่ปอด\n— Appendicitis เป็นการอักเสบของไส้ติ่ง ไม่เกี่ยวกับรอยโรคในปอด\n— Inflammatory bowel disease เป็นภาพที่ Anisakis ในลำไส้เลียนแบบได้ ไม่ใช่พยาธิใบไม้ปอด\n— ภาวะภูมิไวเกินเป็นปฏิกิริยาของภูมิคุ้มกัน ไม่ได้ให้ภาพไอเป็นเลือดเรื้อรังที่ต้องแยกจากพยาธิใบไม้ปอด\n\n💡 ไอเป็นเลือดเรื้อรังในคนที่กินปูดิบ ต้องแยกพยาธิใบไม้ปอดออกจากวัณโรค",
