    "id": 208122,
    "subject": "zoonoses",
    "topic": "zoo-helminthic",
    "year": 5,
    "type": "mcq",
    "examScope": "midterm",
    "q": "ผู้หญิงที่อาศัยอยู่ในจังหวัดพระนครศรีอยุธยาคนหนึ่ง ติดพยาธิอย่างรุนแรงจนเกิดภาวะลำไส้อุดตัน (intestinal obstruction) ผู้ป่วยรายนี้มีโอกาสติดพยาธิชนิดใดมากที่สุด",
    "options": [
      "Gnathostoma",
      "Opisthorchis",
      "Fasciolopsis",
      "Sparganum",
      "Capillaria"
    ],
    "answer": 2,
    "explain": "Fasciolopsis buski เป็นพยาธิใบไม้ลำไส้ขนาดใหญ่ ตัวเต็มวัยเกาะอยู่ที่ผนังลำไส้เล็ก คนติดจากการกินพืชน้ำดิบที่มี metacercaria เกาะอยู่ เช่น สายบัว กระจับ และผักบุ้ง ในไทยเคยพบมากในภาคกลางซึ่งเป็นที่ลุ่มมีนาข้าวและบ่อกระจับ เช่น อยุธยา ถ้าติดพยาธิจำนวนมาก ผนังลำไส้เป็นแผล ปวดท้อง ท้องเสีย ลำไส้อุดตัน บวมทั้งตัว และอาจเสียชีวิตได้ รักษาด้วย praziquantel Fasciolopsis อยู่ในวงศ์ Fasciolidae เดียวกับ Fasciola ชื่อจึงคล้ายกันมาก แต่ Fasciola เป็นพยาธิใบไม้ตับของสัตว์เคี้ยวเอื้องที่อาศัยในท่อน้ำดี ไม่ได้อยู่ในโพรงลำไส้\n\n❌ ทำไมข้ออื่นผิด\n— Gnathostoma เป็นตัวอ่อนที่ไชไปใต้ผิวหนังและอวัยวะต่าง ๆ ไม่ได้อยู่รวมกันจำนวนมากในโพรงลำไส้\n— Opisthorchis อาศัยในท่อน้ำดี ติดจากปลาเกล็ดขาวดิบ และพบมากในภาคอีสาน\n— Sparganum เป็นตัวอ่อนของ Spirometra ที่อยู่ในเนื้อเยื่อ เช่น ใต้ผิวหนังและลูกตา\n— Capillaria philippinensis อยู่ในลำไส้เล็กก็จริง แต่อาการเด่นคือท้องเสียเรื้อรังและการดูดซึมผิดปกติ ไม่ใช่ลำไส้อุดตัน\n\n💡 พืชน้ำดิบในภาคกลางกับพยาธิใบไม้ในลำไส้คือ Fasciolopsis ส่วน Fasciola อยู่ในตับ",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 17",
    "sourceType": "student-compilation",
    "verified": "ZOONOSES MID 86 🏅.pdf หน้า 17 Question 6 (ไฮไลต์ชมพูที่คำว่า อยุธยา และตัวเลือก C. Fasciola ซึ่งเป็นปุ่มที่เลือกไว้); ตัวเลือกในภาพพิมพ์ Fasciola แต่พยาธิใบไม้ที่ทำให้ลำไส้อุดตันเมื่อติดจำนวนมากและเคยชุกในภาคกลางคือพยาธิใบไม้ลำไส้ Fasciolopsis buski ส่วน Fasciola เป็นพยาธิใบไม้ตับในท่อน้ำดี (glossary Fasciola gigantica) และ ZOONOSES MID 86 🏅.pdf หน้า 20เขียนหัวข้อนี้ว่า Fasciolopsiasis ใบไม้ในลำไส้ intestinal obstruction ติดดาว endemic ภาคกลาง กินพืชน้ำดิบ จึงแก้ตัวเลือกเป็น Fasciolopsis; คลิป 2026 gwgmq6oGOWc ไม่ได้สอน ตรวจกับ PubMed: Bhattacharjee et al. 2009 Trop Gastroenterol 30(1):40-1 pmid 19624087 (heavy infestation: abdominal pain, diarrhoea, mucosal ulceration, intestinal obstruction, anasarca, fatality; MeSH จัด F. buski ไว้ใน Fasciolidae วงศ์เดียวกับ Fasciola); Saksirisampant et al. 2006 J Med Assoc Thai 89(11):1928-33 pmid 17205876 (อ่างทอง อยุธยา สุพรรณบุรี ที่ลุ่มนาข้าวและบ่อกระจับ เคยพบ F. buski มากในห้าทศวรรษก่อน แต่การสำรวจครั้งนั้นไม่พบ); Bunnag et al. 1983 Southeast Asian J Trop Med Public Health 14(2):216-9 pmid 6635761 (นักเรียนภาคกลางติดจากสายบัว กระจับ ผักบุ้ง หายด้วย praziquantel); Chai and Jung 2019 Acta Trop 201:105210 doi 10.1016/j.actatropica.2019.105210 (F. buski ติดจากผักน้ำ)",
