    "explain": "Capillaria philippinensis เป็นพยาธิตัวกลมที่มีนกกินปลาเป็นโฮสต์สุดท้ายในธรรมชาติ และมีปลาน้ำจืดเป็นโฮสต์กลาง ไข่ที่ปนมากับอุจจาระนกตกลงน้ำและติดปลา คนติดจากการกินปลาน้ำจืดตัวเล็กดิบ พยาธิเพิ่มจำนวนในลำไส้เล็กของคนได้เองโดยไม่ผ่านสิ่งแวดล้อม (autoinfection) จำนวนพยาธิจึงสูงขึ้นเรื่อย ๆ ทำให้ท้องเสียเรื้อรัง ท้องร้อง ปวดท้อง บวม การดูดซึมอาหารผิดปกติ และเสียโปรตีนกับเกลือแร่ หากไม่รักษาผู้ป่วยเสียชีวิตได้ รักษาด้วยการให้เกลือแร่ร่วมกับ mebendazole หรือ albendazole ผู้ป่วยส่วนใหญ่พบในฟิลิปปินส์และไทย\n\n❌ ทำไมข้ออื่นผิด\n— Gnathostoma มีสุนัขและแมวเป็นโฮสต์สุดท้าย ตัวอ่อนในคนไชไปใต้ผิวหนังและอวัยวะต่าง ๆ\n— Opisthorchis มีคน แมว และสุนัขเป็นโฮสต์สุดท้าย ติดจากปลาเกล็ดขาวดิบ และอาศัยในท่อน้ำดี\n— Schistosoma ตัวเต็มวัยอยู่ในหลอดเลือดดำของสัตว์เลี้ยงลูกด้วยนม คนติดจาก cercaria ที่ไชผิวหนัง\n— Paragonimus ติดจากปูหรือกุ้งน้ำจืดดิบ และตัวเต็มวัยอยู่ในปอด\n\n💡 นกกินปลา ปลาน้ำจืดตัวเล็กดิบ และท้องเสียเรื้อรังจนเสียชีวิตได้ คือ Capillaria philippinensis",
