    "explain": "Spirometra มีโฮสต์กลาง 2 ตัว ตัวที่ 1 คือ Cyclops (copepod) ในน้ำ ซึ่งมีตัวอ่อนระยะ procercoid ตัวที่ 2 คือสัตว์สะเทินน้ำสะเทินบก สัตว์เลื้อยคลาน นก หรือสัตว์เลี้ยงลูกด้วยนมที่กิน Cyclops เข้าไป ตัวอ่อนในโฮสต์กลางตัวที่ 2 เจริญเป็น plerocercoid หรือ sparganum ในเนื้อเยื่อ คนที่ดื่มน้ำไม่สะอาดซึ่งมี Cyclops ติดตัวอ่อน จะมีตัวอ่อนเจริญเป็น sparganum ในร่างกาย คนจึงเป็นโฮสต์กลางตัวที่ 2 ส่วนคนที่กินเนื้อกบหรืองูดิบ หรือพอกเนื้อกบดิบที่ตา ได้ sparganum ที่ไชต่อไปโดยไม่เจริญเป็นระยะใหม่ คนจึงเป็น paratenic host ตัวอ่อนมักพบเป็นก้อนใต้ผิวหนังหรือที่ลูกตา คนเป็นโฮสต์สุดท้ายได้เช่นกันเมื่อตัวตืดเจริญเต็มวัยในลำไส้ แต่ภาวะนั้นคือ spirometriasis ไม่ใช่ sparganosis\n\n❌ ทำไมข้ออื่นผิด\n— โฮสต์สุดท้ายต้องมีตัวตืดเต็มวัยในลำไส้ ซึ่งเป็นภาวะ spirometriasis ไม่ใช่ sparganosis ที่มีตัวอ่อนในเนื้อเยื่อ\n— โฮสต์กลางตัวที่ 1 คือ Cyclops ในน้ำ ซึ่งมีตัวอ่อนระยะ procercoid\n— คนไม่ได้เป็นแหล่งรังโรคของ Spirometra เพราะตัวอ่อนในเนื้อเยื่อคนไม่ถูกส่งต่อไปยังโฮสต์อื่น\n— โฮสต์หลักเป็นอีกชื่อของโฮสต์สุดท้าย ซึ่งต้องมีตัวตืดเต็มวัยในลำไส้\n\n💡 ดื่มน้ำที่มี Cyclops คนเป็นโฮสต์กลางตัวที่ 2 ส่วนกินเนื้อกบดิบ คนเป็น paratenic host",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 18",
