    "type": "mcq",
    "examScope": "midterm",
    "q": "ผู้ป่วยในภาคอีสานที่กินปลาร้าและก้อยปลาดิบเป็นประจำ ตรวจพบไข่พยาธิใบไม้ตับ Opisthorchis viverrini มาหลายปี การติดพยาธินี้เรื้อรังสัมพันธ์กับมะเร็งชนิดใด",
    "options": [
      "มะเร็งเซลล์ตับ (hepatocellular carcinoma)",
      "มะเร็งกระเพาะปัสสาวะ (squamous cell carcinoma)",
      "มะเร็งท่อน้ำดี (cholangiocarcinoma)",
      "มะเร็งกระเพาะอาหาร (gastric adenocarcinoma)",
      "มะเร็งหลังโพรงจมูก (nasopharyngeal carcinoma)"
    ],
    "answer": 2,
    "explain": "ตัวเต็มวัยของ Opisthorchis viverrini อาศัยอยู่ในท่อน้ำดี ท่อน้ำดีจึงอักเสบเรื้อรัง หนาตัวขึ้นเรื่อย ๆ จนตีบ และน้ำดีไหลผ่านได้ไม่ดี ในระดับโมเลกุล สาร excretory-secretory product (ES) ของพยาธิกระตุ้นให้เกิด nitric oxide ความเสียหายต่อ DNA และการกลายพันธุ์ที่ก่อมะเร็ง ปลายทางคือมะเร็งท่อน้ำดี (cholangiocarcinoma หรือ CCA) ซึ่งพบมากในภาคอีสาน ยังไม่มีรายงาน CCA จากพยาธิใบไม้ตับในสัตว์รังโรค เหตุผลที่เสนอไว้คือสัตว์มีช่วงชีวิตสั้นกว่าคน และภูมิคุ้มกันของโฮสต์ต่างกัน คนติดพยาธินี้จากการกินปลาเกล็ดขาว (cyprinoid) ดิบที่มี metacercaria และรักษาด้วย praziquantel แต่ติดซ้ำได้ถ้ายังกินดิบเหมือนเดิม\n\n❌ ทำไมข้ออื่นผิด\n— มะเร็งเซลล์ตับสัมพันธ์กับไวรัสตับอักเสบบี ซี และ aflatoxin ไม่ใช่พยาธิที่อาศัยในท่อน้ำดี\n— มะเร็งกระเพาะปัสสาวะชนิด squamous cell carcinoma สัมพันธ์กับพยาธิใบไม้เลือด Schistosoma haematobium\n— มะเร็งกระเพาะอาหารชนิด adenocarcinoma สัมพันธ์กับการติดเชื้อ Helicobacter pylori\n— มะเร็งหลังโพรงจมูกสัมพันธ์กับไวรัส Epstein-Barr\n\n💡 พยาธิใบไม้ตับอาศัยในท่อน้ำดี มะเร็งที่ตามมาจึงเป็นมะเร็งท่อน้ำดี ไม่ใช่มะเร็งเซลล์ตับ",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 20",
