    "verified": "ZOONOSES MID 86 🏅.pdf หน้า 21 หัวข้อ Sparganosis: ดาวแดงกับ เด็กว่ายน้ำ copepod ที่ชื่อหัวข้อ, ไฮไลต์เหลือง procercoid และ plerocercoid ที่บรรทัด Infection stage, ดาวแดง prevention ไม่กินเนื้อสัตว์ดิบ; ตรวจกับ gwgmq6oGOWc [21:55-24:43] (Spirometra ชนิด manson, intermediate host ตัวที่ 1 Cyclops ตัวที่ 2 นกและสัตว์สะเทินน้ำสะเทินบก, เลี่ยงเนื้อ amphibian ดิบและหมูป่า, ระวังการดื่มน้ำตามแหล่งน้ำ) และ [25:38] (ระยะ larva อาจต้องผ่าตัด); ชื่อระยะ procercoid ใน copepod กับ plerocercoid ในโฮสต์กลางลำดับที่สอง และทางติดสู่คนสองทาง ตรวจกับ CDC DPDx Sparganosis; ไม่ได้ถามบทบาทโฮสต์ของคน เพราะคาบ 2026 ระบุ final host คือ คน สุนัข แมว [24:00] ขณะที่ CDC ระบุว่าคนเป็นเพียง paratenic หรือ second intermediate host; 106139 ถามอาการของ spirometriasis ในลำไส้ ไม่มีข้อใดคีย์ระยะติดต่อหรือทางติดของ sparganosis",
