    "answer": 1,
    "explain": "Trichinella spiralis เป็นพยาธิตัวกลมที่ตัวเต็มวัยอยู่ในลำไส้เล็กเพียงช่วงสั้น ตัวเมียปล่อยตัวอ่อนระยะแรก (L1) ออกมาโดยตรง ตัวอ่อนเข้าสู่กระแสเลือดและน้ำเหลืองไปฝังในเซลล์กล้ามเนื้อลาย แล้วขดตัวอยู่ในซิสต์ (nurse cell) ซึ่งเป็นระยะติดต่อ เมื่อคนหรือสัตว์กินเนื้อที่มีซิสต์ ตัวอ่อนจะออกจากซิสต์ในลำไส้และเจริญเป็นตัวเต็มวัย ซิสต์ในกล้ามเนื้ออยู่ได้ตั้งแต่หลายเดือนถึงหลายปี จากนั้นจะมีหินปูนมาเกาะ (calcification) และตัวอ่อนตายไป คนที่ติดจะปวดท้องและท้องเสียในช่วงแรก ตามด้วยปวดกล้ามเนื้อ ไข้ หนังตาบวม และ eosinophil ในเลือดสูง ในประเทศไทยการระบาดส่วนใหญ่มาจากการกินเนื้อหมูหรือหมูป่าดิบ โดยเฉพาะในภาคเหนือ\n\n❌ ทำไมข้ออื่นผิด\n— ตัวอ่อนของ Trichinella ไม่ได้ออกมากับอุจจาระ การติดต่อเกิดจากการกินเนื้อที่มีซิสต์\n— metacercaria เป็นระยะของพยาธิใบไม้ และการรมควันทำลายตัวอ่อนในเนื้อได้ไม่แน่นอน\n— cysticercus ที่มีตะขอที่หัวเป็นตัวอ่อนของตัวตืด Taenia solium ไม่ใช่พยาธิตัวกลม\n— Trichinella ไม่มีระยะไข่ในเนื้อหรือในสิ่งแวดล้อม ตัวเมียปล่อยตัวอ่อนออกมาโดยตรง\n\n💡 Trichinella ติดจากการกินเนื้อ ระยะติดต่อคือ L1 ในซิสต์ของกล้ามเนื้อลาย ซึ่งกลายเป็นหินปูนเมื่อเวลาผ่านไป",
