    "explain": "Trichinella มีวงจรในสัตว์ป่า (sylvatic cycle) นอกเหนือจากวงจรในหมูบ้าน สัตว์ป่าที่มักเป็นแหล่งติดสู่คน ได้แก่ หมูป่า หมี และสัตว์กินเนื้ออื่น ตัวอ่อนอยู่ในซิสต์ในกล้ามเนื้อลาย การหมักเกลือ การตากแห้ง การรมควัน หรือการอุ่นด้วยไมโครเวฟเพียงอย่างเดียว ทำลายตัวอ่อนได้ไม่สม่ำเสมอ ส่วนการแช่แข็งก็อาจไม่ได้ผลกับเนื้อสัตว์ป่า เพราะ Trichinella บางชนิดที่พบในสัตว์ป่าทนความเย็นได้ วิธีที่ได้ผลคือปรุงให้สุกทั่วถึงจนความร้อนถึงใจกลางเนื้อ ซึ่งวัดได้ด้วยเทอร์โมมิเตอร์สำหรับอาหาร\n\n❌ ทำไมข้ออื่นผิด\n— การรมควันและหมักเกลือทำลายตัวอ่อนได้ไม่สม่ำเสมอ เนื้อที่แปรรูปแบบนี้โดยไม่ปรุงสุกจึงยังเสี่ยง\n— Trichinella มีวงจรในสัตว์ป่า และหมูป่าเป็นแหล่งติดสู่คนที่สำคัญ\n— ตัวอ่อนของ Trichinella อยู่ในกล้ามเนื้อลาย ซึ่งเป็นส่วนที่คนกินโดยตรง\n— Trichinella บางชนิดในสัตว์ป่าทนความเย็นได้ การแช่แข็งเนื้อสัตว์ป่าจึงไม่รับประกันว่าตัวอ่อนตายหมด\n\n💡 เนื้อสัตว์ป่าต้องปรุงให้สุกทั่วถึง การรมควัน หมักเกลือ หรือแช่แข็ง ใช้แทนความร้อนไม่ได้",
