    "answer": 2,
    "explain": "Capillaria philippinensis เป็นพยาธิตัวกลมขนาดเล็กที่เป็นโรคประจำถิ่นในฟิลิปปินส์และประเทศไทย ตัวอ่อนเจริญอยู่ในปลาน้ำจืดขนาดเล็กซึ่งเป็นโฮสต์กลาง คนติดจากการกินปลาน้ำจืดดิบหรือไม่สุกที่มีตัวอ่อนระยะติดต่อ ตัวเต็มวัยฝังอยู่ในเยื่อบุลำไส้เล็ก ตัวเมียบางตัวให้ไข่ที่ฟักเป็นตัวอ่อนได้ภายในลำไส้ ตัวอ่อนนั้นไชกลับเข้าเยื่อบุลำไส้ได้ใหม่ (autoinfection) จำนวนพยาธิจึงเพิ่มขึ้นมากโดยไม่ต้องได้รับเชื้อซ้ำ ผู้ป่วยท้องเสียเรื้อรัง เสียโปรตีนทางลำไส้ (protein-losing enteropathy) ผอมแห้ง และเสียชีวิตได้ถ้าไม่รักษา\n\n❌ ทำไมข้ออื่นผิด\n— C. philippinensis อาศัยในลำไส้เล็กและติดจากปลา ไม่ได้ติดทางการหายใจ ส่วน Capillaria ที่อาศัยในหลอดลมคือ C. aerophila ซึ่งเป็นคนละชนิด\n— ตัวอ่อนในซิสต์ของกล้ามเนื้อลายจากเนื้อหมูดิบเป็นระยะติดต่อของ Trichinella\n— ตัวอ่อนที่ไชผิวหนังเป็นทางติดของพยาธิปากขอ ส่วน C. philippinensis ติดทางการกินปลา และก่อโรครุนแรงได้\n— หอยโข่งดิบกับเยื่อหุ้มสมองอักเสบชนิด eosinophilic เป็นลักษณะของพยาธิปอดหนู Angiostrongylus cantonensis\n\n💡 C. philippinensis ติดจากปลาน้ำจืดดิบ และเพิ่มจำนวนในลำไส้เองได้ จึงถึงตายได้ถ้าไม่รักษา",
