    "explain": "Gnathostoma spinigerum มีสุนัขและแมวเป็นโฮสต์สุดท้าย ไข่ฟักในน้ำ ตัวอ่อนถูก copepod ซึ่งเป็นโฮสต์กลางลำดับแรกกินเข้าไป สัตว์น้ำที่กิน copepod เช่น ปลาน้ำจืดและกบ เป็นโฮสต์กลางลำดับที่สอง ตัวอ่อนเจริญเป็น L3 ระยะหลัง (advanced L3) ขดอยู่ในเนื้อ สัตว์ที่กินโฮสต์กลางเหล่านี้ เช่น งูและสัตว์ปีก เป็น paratenic host ที่เก็บ L3 ไว้โดยไม่เจริญต่อ คนติดจากการกินเนื้อของสัตว์เหล่านี้ที่ปรุงไม่สุก เช่น ปลาไหลหรือปลาช่อนดิบ ส้มฟัก หรือยำกบ คนเป็นโฮสต์บังเอิญ พยาธิไม่เจริญเป็นตัวเต็มวัยที่สืบพันธุ์ได้ ตัวอ่อนเคลื่อนไปตามเนื้อเยื่อ ทำให้บวมเป็นก้อนย้ายที่ใต้ผิวหนังและปวดจี๊ด และไปที่ตาหรือระบบประสาทส่วนกลางได้\n\n❌ ทำไมข้ออื่นผิด\n— ปูน้ำตกที่มี metacercaria เป็นแหล่งติดของพยาธิใบไม้ปอด Paragonimus\n— ตัวอ่อน L1 ในซิสต์ของกล้ามเนื้อหมูเป็นระยะติดต่อของ Trichinella\n— ผักน้ำที่มี metacercaria เกาะเป็นแหล่งติดของ Fasciolopsis และ Fasciola\n— ปลาทะเลและหมึกดิบที่มีตัวอ่อน L3 เป็นแหล่งติดของ Anisakis ไม่ใช่พยาธิตัวจี๊ด\n\n💡 พยาธิตัวจี๊ดมากับปลาน้ำจืด กบ งู และสัตว์ปีกที่ไม่สุก คนเป็นโฮสต์บังเอิญที่ตัวอ่อนเดินไปตามเนื้อเยื่อ",
