    "explain": "Angiostrongylus cantonensis (พยาธิปอดหนู) ตัวเต็มวัยอาศัยในหลอดเลือดแดงปอดของหนู ซึ่งเป็นโฮสต์สุดท้าย ตัวอ่อน L1 ออกมากับมูลหนู หอยทากบก หอยโข่ง หอยเชอรี่ และทากกินเข้าไป ตัวอ่อนเจริญเป็น L3 ระยะติดต่อในหอย คนติดจากการกินหอยดิบหรือไม่สุก ผักสดที่มีหอยหรือทากตัวเล็กติดมา หรือ paratenic host เช่น กุ้งน้ำจืด ปูบก และตะกวด คนเป็นโฮสต์บังเอิญ ตัวอ่อนเดินทางไปที่สมองและตายอยู่ที่นั่นโดยไม่ครบวงจร ตัวอ่อนและปฏิกิริยาของร่างกายต่อตัวอ่อนทำให้เยื่อหุ้มสมองอักเสบชนิด eosinophilic (eosinophilic meningitis) ผู้ป่วยปวดศีรษะรุนแรง คอแข็ง และน้ำไขสันหลังมี eosinophil สูง ผู้ป่วยส่วนใหญ่หายได้เป็นปกติ\n\n❌ ทำไมข้ออื่นผิด\n— cysticercus ของ Taenia solium เกิดจากการกลืนไข่ตัวตืด ไม่ได้อยู่ในหอย\n— Streptococcus suis ติดจากเนื้อหรือเลือดหมูดิบ ไม่ได้มากับหอย และเยื่อหุ้มสมองอักเสบจากแบคทีเรียมี neutrophil เด่นในน้ำไขสันหลัง\n— metacercaria ของ Paragonimus อยู่ในปูและกุ้งน้ำจืด ไม่ใช่ในหอยที่คนกิน\n— หลอดเลือดแดงปอดเป็นที่อยู่ของตัวเต็มวัยในหนู ในคนพยาธิไม่เจริญเป็นตัวเต็มวัย\n\n💡 เยื่อหุ้มสมองอักเสบหลังกินหอยดิบ ให้นึกถึงพยาธิปอดหนู และตรวจพบ eosinophil สูงในน้ำไขสันหลัง",
