    "answer": 2,
    "explain": "Schistosoma เป็นพยาธิใบไม้ที่ตัวเต็มวัยอาศัยอยู่ในหลอดเลือดดำ ไข่ออกมากับอุจจาระหรือปัสสาวะลงน้ำ ฟักเป็น miracidium ที่ไชเข้าหอยน้ำจืด แล้วเจริญผ่าน sporocyst สองรุ่นเป็น cercaria ที่มีหางแฉก cercaria ว่ายออกจากหอยและไชผ่านผิวหนังของคนขณะลงแหล่งน้ำ จากนั้นสลัดหางเป็น schistosomulum เดินทางไปตามหลอดเลือดจนเจริญเป็นตัวเต็มวัย วงจรนี้ไม่มีระยะ metacercaria คนจึงไม่ได้ติดจากการกินอาหาร ยาที่แนะนำสำหรับ schistosomiasis ทุกรูปแบบคือ praziquantel ซึ่งใช้ทั้งรักษารายบุคคลและให้ยาแก่ประชากรกลุ่มใหญ่ในพื้นที่ระบาด\n\n❌ ทำไมข้ออื่นผิด\n— schistosome ไม่มีระยะ metacercaria และ albendazole ไม่ใช่ยาที่ใช้รักษาพยาธิใบไม้เลือด\n— ทางติดถูกต้อง แต่ albendazole เป็นยาของพยาธิตัวกลมและตัวตืดบางชนิด ไม่ใช่ยาของ schistosomiasis\n— หอยเป็นโฮสต์กลางที่ปล่อย cercaria ออกมาในน้ำ คนไม่ได้ติดจากการกินหอย และ ivermectin ไม่ใช้รักษาพยาธิใบไม้\n— praziquantel ถูกต้อง แต่ metacercaria ในปลาน้ำจืดเป็นระยะติดต่อของพยาธิใบไม้ตับ ไม่ใช่ Schistosoma\n\n💡 พยาธิใบไม้เลือดติดทางผิวหนังจาก cercaria ในน้ำ ไม่ได้ติดทางการกิน และรักษาด้วย praziquantel",
