    "explain": "schistosomiasis ระยะเฉียบพลัน หรือ Katayama fever เป็นปฏิกิริยาภูมิไวเกินต่อพยาธิที่กำลังเจริญในร่างกาย เกิดหลังติดเชื้อหลายสัปดาห์ มีไข้ ไอ ปวดท้อง ผื่น และ eosinophil ในเลือดสูงเป็นลักษณะเด่น ส่วนระยะเรื้อรังเกิดจากไข่ที่ติดค้างในเนื้อเยื่อแล้วกระตุ้นการอักเสบแบบ granuloma และพังผืด S. haematobium อาศัยในกลุ่มหลอดเลือดดำรอบกระเพาะปัสสาวะ ไข่ออกมากับปัสสาวะ ผู้ป่วยปัสสาวะเป็นเลือด ผนังกระเพาะปัสสาวะมีพังผืดและหินปูน และเสี่ยงต่อมะเร็งกระเพาะปัสสาวะชนิด squamous cell carcinoma\n\n❌ ทำไมข้ออื่นผิด\n— ไข้กับ eosinophil สูงหลังลงน้ำเข้ากับ Katayama fever แต่มะเร็งท่อน้ำดีเป็นผลของพยาธิใบไม้ตับ Opisthorchis ไม่ใช่ S. haematobium\n— cercarial dermatitis เป็นผื่นคันเฉพาะที่ตรงที่ cercaria ไช เกิดภายในไม่กี่ชั่วโมงถึงไม่กี่วัน ไม่ใช่อาการทั้งร่างกายหลังหลายสัปดาห์\n— eosinophilic meningitis เป็นลักษณะของพยาธิปอดหนู และมะเร็งเซลล์ตับสัมพันธ์กับไวรัสตับอักเสบ ไม่ใช่ S. haematobium\n— cercarial dermatitis ไม่เข้ากับไข้และ eosinophil สูงหลังหลายสัปดาห์ และมะเร็งท่อน้ำดีเป็นผลของพยาธิใบไม้ตับ\n\n💡 ระยะเฉียบพลันคือ Katayama fever ที่มี eosinophil สูง ระยะเรื้อรังของ S. haematobium คือโรคของกระเพาะปัสสาวะ",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 20",
