    "answer": 0,
    "explain": "Fasciolopsis buski เป็นพยาธิใบไม้ลำไส้ที่ใหญ่ที่สุดในคน ยาว 20 ถึง 75 มิลลิเมตร ตัวเต็มวัยเกาะผนังลำไส้เล็กของคนและหมู ซึ่งเป็นโฮสต์สุดท้ายทั้งคู่ ไข่ออกมากับอุจจาระ ฟักในน้ำ และเจริญในหอย จากนั้น cercaria ออกมาเกาะเป็นซิสต์ (metacercaria) บนพืชน้ำ เช่น กระจับและแห้ว คนติดจากการกินพืชน้ำดิบหรือใช้ฟันแกะเปลือกพืชน้ำ พบในพื้นที่ที่เลี้ยงหมูร่วมกับปลูกพืชน้ำ ผู้ติดเชื้อส่วนใหญ่ไม่แสดงอาการ แต่ถ้าติดจำนวนมากจะท้องเสีย ปวดท้อง บวมน้ำ และลำไส้อุดตันได้ รักษาด้วย praziquantel และป้องกันด้วยการทำพืชน้ำให้สุกก่อนกิน\n\n❌ ทำไมข้ออื่นผิด\n— พยาธิใบไม้ที่อยู่ในท่อน้ำดีและติดจากปลาเกล็ดขาวคือ Opisthorchis viverrini\n— พยาธิใบไม้ที่อยู่ในปอดและติดจากปูน้ำตกคือ Paragonimus\n— พยาธิใบไม้ในหลอดเลือดดำที่ติดจาก cercaria ไชผิวหนังคือ Schistosoma\n— ตัวตืดจากเนื้อวัวดิบที่มีปล้องหลุดออกมากับอุจจาระคือ Taenia saginata\n\n💡 พืชน้ำดิบนึกถึง Fasciolopsis ในลำไส้ ปลาเกล็ดขาวนึกถึงตับ ปูน้ำตกนึกถึงปอด",
