    "answer": 2,
    "explain": "การยืนยันว่าสิ่งที่เห็นเป็น cyst ของ Giardia ต้องเห็นโครงสร้างภายใน คือนิวเคลียส 4 เม็ดและ median body ซึ่งมองไม่ชัดในอุจจาระสดที่ไม่ย้อม Lugol's iodine ย้อมได้ทั้ง cyst และ trophozoite ทำให้นิวเคลียสตัดกับพื้นชัดขึ้น จึงแยก Giardia ออกจาก pseudoparasite ที่รูปร่างคล้ายกันแต่ไม่มีโครงสร้างภายใน เช่น ยีสต์ เรณู และเศษพืช น้ำยาต้องเป็น Lugol's iodine ที่เตรียมใหม่ภายในราว 1 สัปดาห์ ใช้เบตาดีนหรือทิงเจอร์ไอโอดีนแทนไม่ได้ ส่วนการดู trophozoite เคลื่อนที่แบบใบไม้ร่วงต้องดูใน wet mount ที่ผสมน้ำเกลือและยังไม่ย้อม เพราะไอโอดีนทำให้เชื้อหยุดเคลื่อนที่\n\n❌ ทำไมข้ออื่นผิด\n— ไอโอดีนทำให้ trophozoite หยุดเคลื่อนที่ การดูการเคลื่อนที่แบบใบไม้ร่วงจึงต้องทำใน wet mount ที่ยังไม่ย้อม\n— การย้อมให้ติดสีแดงแบบ acid-fast คือ modified Ziehl-Neelsen ที่ใช้หา oocyst ของ Cryptosporidium ไม่ใช่หน้าที่ของ Lugol's iodine\n— Lugol's iodine เป็นสีย้อม ไม่ใช่น้ำยาลอยตัว การลอย cyst ของ Giardia ใช้ zinc sulfate ความถ่วงจำเพาะ 1.18\n— assemblage ของ Giardia แยกด้วยการตรวจทางอณูชีววิทยา รูปร่างและการติดสีแยกกันไม่ได้\n\n💡 Lugol's iodine ย้อมให้เห็นนิวเคลียสและ median body เพื่อแยก Giardia จากยีสต์ แต่การดูการเคลื่อนที่ต้องไม่ย้อม",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 32",
    "sourceType": "student-compilation",
    "verified": "ZOONOSES MID 86 🏅.pdf น.32 Question 10 (ข้อใดผิดสำหรับการวินิจฉัย Giardiasis) ไฮไลต์ชมพูที่ตัวเลือก B การตรวจหา trophozoite ต้องใช้ wet fecal smear เท่านั้น พร้อมโน้ตลายมือสีม่วงข้างตัวเลือกว่า X Lugol ก็ทำได้ และตัวเลือก D หยด Lugol's iodine เพื่อย้อม cyst ดูโครงสร้างภายในให้แน่ใจว่าไม่ใช่ pseudoparasite (ข้อความที่ถูก ไม่มีเครื่องหมาย); คีย์ของข้อคือ E สารละลาย flotation ที่เหมาะคือน้ำตาลเข้มข้น (ไฮไลต์เขียวและขีดเส้นใต้แดง) ซึ่งอยู่ใน 106135; โน้ตข้าง B ชี้ว่า Lugol ย้อม trophozoite ได้ด้วย ซึ่งตรงกับสไลด์ แต่คีย์ยังเป็น E เพราะข้อผิดที่ชัดคือน้ำตาลเข้มข้น; Zoonosis Mid 86(1).pdf น.24 ข้อเดียวกันมีโน้ตว่าห้ามย้อมเพราะเชื้อจะหยุดเคลื่อนที่; ตรวจกับ 6 - Protozoal_zoonosis_(Dr._Woraporn).pdf Dx: Giardia (อ่านข้อความจาก PDF: Lugol's iodine solution staining, Stain trophozoites and cysts, Increase contrast of the nuclei within the organisms) และลายมือบนสไลด์เดียวกันเหนือกรอบ Dx ว่า cyst หน้าตาคล้าย pseudoparasite = ต้องย้อม Lugol's iodine; v6uVIpRJxZU (com5) [31:23]-[32:26] (ต้องเห็น median body และนิวเคลียส 4 เม็ด, สิ่งที่คล้าย Giardia แต่ไม่มีโครงสร้างภายในอาจเป็น yeast หรือ pollen, ในอึสดเห็นไม่ชัดต้องหยด Lugol's iodine เบตาดีนและทิงเจอร์ไอโอดีนใช้ไม่ได้ เตรียมใหม่ภายใน 1 สัปดาห์, trophozoite motility แบบ falling leaf), notes-y2-parasit-1 Giardia: Dx (Lect 7 Part 1 Lugol's ย้อมทั้ง trophozoite และ cyst; ZnSO4 SG 1.18; Pseudoparasites: yeasts, plant remnants and debris) และ (assemblage จำแนกด้วย molecular epidemiology), notes-com5 Giardia Diagnosis และ Cryptosporidium (Modified acid-fast Ziehl-Neelsen); ไอโอดีนทำให้เชื้อหยุดเคลื่อนที่ตามเอกสารน้ำยา Lugol's Iodine ของ Dalynn Biologicals (SL95: iodine tends to paralyze the motility of parasitic organisms จึงให้ตรวจ wet mount ก่อนหยดไอโอดีน) ตรงกับคำอธิบายของ 208070; ไม่มีข้อใดในคลัง ไฟล์ 0925 หรือ fill.json ที่คีย์ Lugol's iodine; ไม่มีคลิปบรรยาย protozoa ปี 2026 ในคลัง และสไลด์ปี 2569 (library doc protozoal-zoonoses-dr-woraporn-4c615e) ยังไม่ได้เปิดเทียบ จึงยืนยันกับสไลด์ของผู้สอนฉบับพิมพ์ 22 พ.ย. 2567",
