    "answer": 4,
    "explain": "Giardia ขับ cyst ออกมากับอุจจาระเป็นช่วง ไม่ได้ออกทุกวันหรือทุกครั้งที่ถ่าย ผลตรวจที่เป็นลบเพียงครั้งเดียวจึงตัดโรคออกไม่ได้ ต้องเก็บอุจจาระตรวจซ้ำในวันต่างกัน และอาจใช้หลายวิธีร่วมกันเพื่อยืนยัน เช่น ชุดตรวจแอนติเจนที่จับโปรตีนผนัง cyst วิธีหา cyst ที่เหมาะคือ centrifugal flotation ด้วย zinc sulfate ความถ่วงจำเพาะ 1.18 แล้วหยด Lugol's iodine ดูนิวเคลียสภายใน\n\n❌ ทำไมข้ออื่นผิด\n— ผลลบครั้งเดียวไม่ได้แปลว่าไม่ติดเชื้อ เพราะ cyst ไม่ได้ออกมากับอุจจาระทุกครั้ง\n— น้ำตาลเข้มข้นทำให้ cyst ของ Giardia หดและบิดเบี้ยวจนดูรูปร่างไม่ได้ น้ำยาที่เหมาะคือ zinc sulfate แบบ centrifugal flotation\n— modified Ziehl-Neelsen ใช้ย้อม oocyst ของ Cryptosporidium ให้ติดสีแดง ไม่ใช้หา cyst ของ Giardia\n— ระยะก่อนพบเชื้อของ Giardia ในสุนัขราว 1 ถึง 2 สัปดาห์ สุนัขที่ท้องเสียเรื้อรังพ้นระยะนั้นไปนานแล้ว\n\n💡 ไม่เจอ cyst ครั้งแรกยังตัด Giardia ออกไม่ได้ ให้ตรวจซ้ำหลายวันด้วย zinc sulfate flotation",
