    "q": "คนหนึ่งชอบกินสเต็กหมูแบบ medium rare ซึ่งอุณหภูมิภายในเนื้อราว 55°C ข้อใดถูกต้องเกี่ยวกับความเสี่ยงต่อการติดเชื้อ Toxoplasma gondii",
    "options": [
      "ไม่เสี่ยง เพราะ tissue cyst ในเนื้อหมูตายหมดเมื่ออุณหภูมิภายในถึงราว 50°C",
      "ยังเสี่ยง ต้องปรุงจนอุณหภูมิภายในถึงราว 66°C หรือจนตรงกลางไม่มีสีชมพู",
      "ไม่เสี่ยง เพราะสุกรไม่ใช่โฮสต์ของ Toxoplasma กล้ามเนื้อหมูจึงไม่มี tissue cyst",
      "ไม่เสี่ยง ถ้าเนื้อหมูผ่านการแช่ตู้เย็นที่ 4°C มาก่อนอย่างน้อย 24 ชั่วโมง",
      "ยังเสี่ยง ต้องต้มถึง 100°C เพราะ tissue cyst ทนความร้อนได้แบบสปอร์แบคทีเรีย"
    ],
    "answer": 1,
    "explain": "เนื้อหมูเป็นแหล่งสำคัญของ tissue cyst ของ Toxoplasma gondii เพราะสุกรเป็นโฮสต์กึ่งกลางที่มี tissue cyst ซึ่งบรรจุ bradyzoite อยู่ในกล้ามเนื้อ การปรุงแบบ medium rare ที่อุณหภูมิภายในราว 55°C ยังไม่ร้อนพอจะทำลาย tissue cyst การกินสเต็กแบบนี้จึงยังเสี่ยงติดเชื้อ การป้องกันคือปรุงเนื้อจนอุณหภูมิภายในถึงราว 66°C (150°F) หรือจนตรงกลางไม่มีสีชมพู หรือแช่แข็งเนื้ออย่างน้อย 24 ชั่วโมงก่อนนำมาปรุง ส่วนการแช่ตู้เย็นธรรมดาไม่ทำลาย tissue cyst แนวทางความปลอดภัยอาหารของ USDA และ CDC ปัจจุบันใช้ 63°C สำหรับเนื้อชิ้นใหญ่แล้วพักไว้ 3 นาที ซึ่งก็ยังสูงกว่า 55°C\n\n❌ ทำไมข้ออื่นผิด\n— tissue cyst ไม่ตายที่ราว 50°C ต้องใช้ความร้อนสูงกว่านั้นมาก เนื้อที่ร้อนเพียง 55°C จึงยังมีเชื้อที่ติดต่อได้\n— สุกรเป็นโฮสต์กึ่งกลางของ Toxoplasma และมี tissue cyst ในกล้ามเนื้อได้ เนื้อหมูปรุงไม่สุกจึงเป็นทางติดหลักทางหนึ่ง\n— อุณหภูมิตู้เย็นราว 4°C ไม่ทำลาย tissue cyst สิ่งที่ช่วยได้คือการแช่แข็งอย่างน้อย 24 ชั่วโมง\n— tissue cyst ไม่ได้ทนความร้อนแบบสปอร์แบคทีเรีย อุณหภูมิภายในราว 66°C ก็ทำลายได้ ไม่จำเป็นต้องต้มถึง 100°C\n\n💡 สเต็กหมู medium rare 55°C ยังเสี่ยง Toxoplasma ต้องสุกถึงราว 66°C หรือแช่แข็งก่อน",
    "source": "ZOONOSES MID 86 🏅.pdf หน้า 30",
    "sourceType": "student-compilation",
    "verified": "ZOONOSES MID 86 🏅.pdf น.30 Question 8 (กิจกรรมใดไม่เสี่ยงต่อการติดเชื้อ Toxoplasma) ภาพหน้าจอข้อสอบออนไลน์ที่บันทึกไว้ ตัวเลือก D กินสเต็กหมูแบบ medium rare (กึ่งสุกกึ่งดิบ) อุณหภูมิข้างในเนื้อ 55°C เป็นกิจกรรมที่เสี่ยง (ไม่มีเครื่องหมายบนตัวเลือกนี้; คีย์ของข้อคือ A ลูบขนแมว ไฮไลต์ชมพูและขีดเส้นใต้แดง ซึ่งอยู่ใน 106128); ตรวจกับ 6 - Protozoal_zoonosis_(Dr._Woraporn).pdf (อ่านข้อความจาก PDF: Do not eat undercooked or raw red meat; Inside temp. reaches 150ºF (66ºC) or no longer pink in the center; Frozen for at least 24 hours, smoked or cured) และ wrapups/zoonoses.js zoo-protozoal (66°C หรือแช่แข็งอย่างน้อย 24 ชั่วโมง อ้างสไลด์; tissue cyst ตายที่ราว 67°C ตาม Dubey และ Kotula et al. 1991 J Food Prot 54(9):687-90 เรื่องการแช่แข็ง), notes-y2-parasit-1 Toxoplasma (หนู สุกร และสัตว์เคี้ยวเอื้องขนาดเล็กมัก harbor tissue cyst); แนวทาง USDA FSIS และ CDC ปัจจุบัน 145°F (63°C) สำหรับเนื้อชิ้นใหญ่แล้วพัก 3 นาที ต่างจากสไลด์ คีย์จึงตามสไลด์และคำอธิบายระบุแนวทางนี้หนึ่งบรรทัด; ไม่มีข้อใดในคลัง ไฟล์ 0925 หรือ fill.json ที่คีย์อุณหภูมิปรุงเนื้อ (106128 และ 106132 มีเพียงเนื้อปรุงไม่สุกเป็นความเสี่ยง); ไม่มีคลิปบรรยาย protozoa ปี 2026 ในคลัง และสไลด์ปี 2569 (library doc protozoal-zoonoses-dr-woraporn-4c615e) ยังไม่ได้เปิดเทียบ จึงยืนยันกับสไลด์ของผู้สอนฉบับพิมพ์ 22 พ.ย. 2567",
