    "explain": "Leishmania ถ่ายทอดสู่คนผ่านการกัดของ phlebotomine sandfly (ริ้นฝอยทราย) เพศเมียเท่านั้น เพราะเฉพาะเพศเมียที่ต้องดูดเลือดเพื่อนำโปรตีนไปสร้างไข่ ส่วนเพศผู้กินน้ำหวานจากพืชและไม่กัดคนหรือสัตว์ sandfly เพศเมียได้รับ amastigote ที่อยู่ใน macrophage ขณะดูดเลือดสุนัขที่เป็นแหล่งรังโรคของ L. infantum เชื้อเปลี่ยนเป็น promastigote และเพิ่มจำนวนในทางเดินอาหารของแมลง แล้วเคลื่อนไปที่ส่วนปากและเข้าสู่ผิวหนังคนเมื่อแมลงดูดเลือดครั้งถัดไป\n\n❌ ทำไมข้ออื่นผิด\n— sandfly ทั้งสองเพศผิด เพราะเพศผู้ไม่ดูดเลือด จึงไม่ได้รับเชื้อและไม่ถ่ายทอดเชื้อ\n— ยุงก้นปล่องเพศเมียเป็นพาหะของ Plasmodium ที่ก่อโรคมาลาเรีย ไม่ใช่ Leishmania\n— แมลงวัน tsetse ดูดเลือดทั้งสองเพศและเป็นพาหะของ Trypanosoma brucei ในแอฟริกา ไม่ใช่ Leishmania\n— แมลงวันคอกสัตว์ดูดเลือดทั้งสองเพศและนำ Trypanosoma evansi ที่ก่อโรค surra แบบ mechanical ไม่ใช่พาหะของ Leishmania\n\n💡 sandfly เหมือนยุง คือเฉพาะเพศเมียที่ดูดเลือดและนำเชื้อ",
