    "verified": "ZOONOSES MID 86 🏅.pdf น.37 Question 15 (คนติดเชื้อ Leishmania จากสัตว์ได้อย่างไร) ไฮไลต์ชมพูและขีดเส้นใต้แดงที่ E. Sand fly ที่มีเชื้อมาดูดเลือด พร้อมโน้ตลายมือสีม่วงข้างคำตอบว่า sandfly ตัว♀ only; การติดผ่าน sandfly มีใน 208009 แล้ว แต่ยังไม่มีข้อใดทดสอบว่าเฉพาะเพศเมียเป็นพาหะ (ข้อใน coverage/fill.json เรื่อง Culicoides ก็ไม่ได้ทดสอบเพศ); ไม่มีคลิปบรรยาย protozoa ปี 2026 ในคลัง และคลิป 2026 ที่มีอยู่ไม่ได้พูดถึง sandfly จึงไม่มีข้อขัดแย้ง; notes-y5-zoonoses กับ notes-85-zoonoses ไม่ได้ระบุเพศของพาหะ จึงตรวจกับ notes-y2-parasit-1 Lect 7 Part 2 Hemoflagellates (Leishmania ทุกสปีชีส์ถ่ายทอดโดย female sandflies ที่ดูดเลือด; amastigote เปลี่ยนเป็น promastigote ใน midgut แล้วเคลื่อนไป foregut และ proboscis) และ (vector-borne disease ถ่ายทอดผ่านการกัดของ female phlebotomine sandfly) กับ WHO Leishmaniasis fact sheet (transmitted by the bites of infected female phlebotomine sandflies); สุนัขเป็นแหล่งรังโรคของ L. infantum ตรวจกับ notes-y5-zoonoses zoo-protozoal 3) Metazoonoses (Phlebotomine sandflies carrying Leishmania from dogs to humans); ตัวลวงตรวจกับ notes-y5-zoonoses zoo-protozoal แถว Vector-borne (mosquito/sandfly/tsetse fly: Leishmania, Trypanosoma, Babesia, Plasmodium), notes-y2-parasit-1 Lect 7 Part 2 Hemoflagellates (T. brucei มี tsetse fly เป็นพาหะแบบ Salivarian; T. evansi โรค Surra มี Tabanid fly และ Stable fly เป็นพาหะแบบ mechanical) และ CDC African trypanosomiasis biology (tsetse ดูดเลือดทั้งสองเพศ); Anopheles ดูดเลือดเฉพาะเพศเมีย และ Stomoxys calcitrans ดูดเลือดทั้งสองเพศ เป็นข้อเท็จจริงมาตรฐานทางกีฏวิทยา",
