    "explain": "7-1-7 เป็นมาตรฐานระดับโลกด้านความทันเวลาของการควบคุมการระบาด ตัวเลขทั้งสามเป็นหน่วยวันทั้งหมดและนับต่อกันเป็นช่วง ช่วงแรกคือตรวจจับเหตุการณ์ให้ได้ภายใน 7 วันนับจาก date of emergence ช่วงที่สองคือแจ้งเตือนหน่วยงานที่ทำหน้าที่ควบคุมโรคภายใน 1 วันหลังตรวจจับ และช่วงสุดท้ายคือเริ่มมาตรการตอบสนองเบื้องต้นทั้ง 7 ข้อให้ครบภายใน 7 วันหลังแจ้ง date of emergence ของโรคที่ไม่ใช่โรคประจำถิ่นคือวันที่ index case หรือผู้ป่วยรายแรกที่เชื่อมโยงทางระบาดวิทยาเริ่มมีอาการ ส่วนโรคประจำถิ่นคือวันที่จำนวนผู้ป่วยเพิ่มขึ้นเกินค่าพื้นฐานตามเกณฑ์ที่ตั้งไว้ การควบคุมโรคให้อยู่ต้องทั้งทันเวลาและมีคุณภาพ มาตรฐานนี้วัดด้านความทันเวลา และปัจจุบันใช้กับงานด้านปศุสัตว์และสัตว์ป่าด้วย\n\n❌ ทำไมข้ออื่นผิด\n— นับเป็นชั่วโมงผิดหน่วย 7-1-7 นับเป็นวันทั้งหมด กรอบที่นับเป็นชั่วโมงคือการแจ้งโรคติดต่ออันตรายภายใน 3 ชั่วโมงและลงสอบสวนภายใน 12 ชั่วโมง\n— เรียงผิดช่วง เลข 7 ตัวแรกคือการตรวจจับ เลข 1 คือการแจ้งเตือน และการส่งรายงานไม่ได้เป็นตัวชี้วัดของมาตรฐานนี้\n— การยืนยันเชื้อด้วยห้องปฏิบัติการเป็นหนึ่งใน 7 มาตรการของช่วงตอบสนองเบื้องต้น ไม่ใช่ช่วง 1 วัน และมาตรฐานนี้ไม่ได้กำหนดวันประกาศสิ้นสุดการระบาด\n— ช่วงสุดท้ายวัดว่าเริ่มมาตรการเบื้องต้นครบภายใน 7 วันหรือไม่ ไม่ได้วัดว่าการระบาดสงบเมื่อใด และไม่ได้นับเป็นสัปดาห์\n\n💡 7-1-7 เป็นวันทั้งหมด อ่านเรียงว่า ตรวจจับ แจ้ง แล้วตอบสนอง",
    "source": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf หน้า 35",
