    "verified": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf น.35 (หน้าเรื่อง 7-1-7: ดาวแดงสองดวงข้างโลโก้ พร้อมโน้ตแดง หน่วยเป็นวันทั้งหมด และ เป็นมาตรการที่เน้นเรื่องเวลา ต้องควบคุมให้เร็ว, ไฮไลต์ม่วงที่ Detect, Notify, Response พร้อมโน้ต แจ้งเตือนหน่วยงานควบคุมโรค และ ต้องรีบทำมาตรการเบื้องต้น, นิยาม date of emergence แบบ endemic, non-endemic และ other health threat อยู่บนหน้าเดียวกัน) และ น.34 (โน้ต ถ้ารู้เร็วและแยกเร็ว การระบาดก็จะไม่เกิด ใต้ข้อความ detect, notify, and respond early); ตรวจกับ _NpT5OMLkUk [89:03]-[90:26] (ขอให้จำเลขชุดนี้, ทันเวลาและมีคุณภาพ [89:36]-[89:47], Date of Emergence [89:55], detect 7 วัน [90:07], notify 1 วันไปยังหน่วยงานที่ควบคุมโรค [90:15]-[90:23], complete early response 7 วัน [90:26], ขยายไปใช้ในปศุสัตว์และสัตว์ป่า [89:10]-[89:23]); การนับแต่ละช่วงต่อจากช่วงก่อนตามกรอบ Frieden TR et al. Lancet 2021;398:638-40",
