    "explain": "มาตรการตอบสนองเบื้องต้นของ 7-1-7 มี 7 ข้อ คือ 1) ส่งทีมสอบสวนหรือทีมตอบโต้ลงพื้นที่ 2) วิเคราะห์ทางระบาดวิทยาและประเมินความเสี่ยงเบื้องต้น 3) ยืนยันสาเหตุของการระบาดด้วยห้องปฏิบัติการ 4) จัดการผู้ป่วยและทำ IPC ในสถานพยาบาล 5) ใช้มาตรการสาธารณสุขในชุมชนที่ได้รับผลกระทบ 6) สื่อสารความเสี่ยงและให้ชุมชนมีส่วนร่วม 7) ตั้งกลไกประสานงาน ทั้ง 7 ข้อต้องเริ่มให้ครบภายใน 7 วันหลังแจ้งเตือน ส่วน after-action review เป็นการถอดบทเรียนเมื่อเหตุการณ์ผ่านไปแล้ว เพื่อหาจุดติดขัดและปรับปรุงรอบหน้า จึงอยู่ท้ายขั้น Response ของการสอบสวน ไม่ใช่มาตรการเบื้องต้นที่ต้องเริ่มภายใน 7 วัน\n\n❌ ทำไมข้ออื่นผิด\n— การส่งทีมลงพื้นที่เป็นมาตรการที่ 1 ของ 7 ข้อ\n— การยืนยันสาเหตุด้วยห้องปฏิบัติการเป็นมาตรการที่ 3 ของ 7 ข้อ\n— การจัดการผู้ป่วยร่วมกับ IPC (infection prevention and control) ในสถานพยาบาลเป็นมาตรการที่ 4 เพื่อกันไม่ให้เชื้อแพร่ในสถานพยาบาลและสู่บุคลากรทางการแพทย์\n— RCCE (risk communication and community engagement) เป็นมาตรการที่ 6 ของ 7 ข้อ\n\n💡 7 ข้อไล่เป็น ทีม ประเมินความเสี่ยง แล็บ สถานพยาบาล ชุมชน สื่อสาร ประสานงาน",
