    "explain": "การสอบสวนการระบาดมี 3 ขั้นที่เดินไปพร้อมกันระหว่างลงพื้นที่ Describe คือพรรณนาให้ได้ว่าเกิดอะไรขึ้น เริ่มจากเตรียมคน เงิน และอุปกรณ์สำหรับงานภาคสนาม ยืนยันการวินิจฉัย (verify the diagnosis) ว่าเป็นโรคนั้นจริง ยืนยันว่าเกิดการระบาดจริง (confirm the outbreak) ไม่ใช่ผลบวกจากการปนเปื้อนในห้องปฏิบัติการ ตั้งนิยามผู้ป่วย (case definition) แล้วค้นหาผู้ป่วยเพิ่มเติมเชิงรุก (active case finding) ด้วยการถามต่อเป็นทอด (snowball technique) การเคาะประตูบ้าน หรือการทำประชาคม และทำระบาดวิทยาเชิงพรรณนาตามบุคคล เวลา สถานที่ รวมถึงมองหา outlier Explain คืออธิบายว่าเกิดเพราะอะไร โดยตั้งสมมติฐานเรื่องสาเหตุและปัจจัยเสี่ยง แล้วทดสอบด้วย analytical study เช่น case-control, cohort หรือ cross-sectional และทำการศึกษาเพิ่มเติมตามความเหมาะสม เช่น ตรวจห้องปฏิบัติการหรือสิ่งแวดล้อม Response คือเสนอและดำเนินมาตรการป้องกันควบคุมโรค นำเสนอผลและติดตามมาตรการ แล้วทำ debrief หรือ after-action review เพื่อปรับปรุงรอบหน้า\n\n❌ ทำไมข้ออื่นผิด\n— ยืนยันการวินิจฉัยต้องมาก่อนการตั้งสมมติฐาน เพราะถ้ายังไม่รู้ว่าเป็นโรคอะไรจริง สมมติฐานเรื่องสาเหตุก็ไม่มีฐาน งานยืนยันจึงอยู่ใน Describe ส่วนการทดสอบสมมติฐานอยู่ใน Explain\n— การทดสอบสมมติฐานเป็นงานของ Explain ส่วน after-action review เป็นงานปิดท้ายของ Response สองงานนี้สลับขั้นกัน\n— การวางมาตรการและถอดบทเรียนเป็นงานของ Response ส่วนการยืนยันการวินิจฉัยและการระบาดเป็นงานตั้งต้นของ Describe\n— ผิดทั้งสามคู่ Describe ไม่ได้ทดสอบสมมติฐาน Explain ไม่ได้วางมาตรการ และ Response ไม่ใช่ขั้นยืนยันการวินิจฉัย\n\n💡 Describe เกิดอะไร Explain เกิดเพราะอะไร Response ทำอะไรต่อ",
    "source": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf หน้า 44",
