    "explain": "งานของนักระบาดวิทยาภาคสนามเริ่มจาก surveillance เพื่อระบุปัญหา ระบบเฝ้าระวังเปรียบเหมือนตาของระบบ แต่ตัวเลขที่รายงานเข้ามาเป็นเพียงยอดภูเขาน้ำแข็ง จึงต้องตามด้วย investigation และการศึกษาทางระบาดวิทยา โดยเข้าไปอยู่ในพื้นที่จริงเพื่อเข้าใจบริบทและหาปัจจัยเสี่ยงกับปัจจัยป้องกัน จากนั้นจึงออกมาตรการป้องกันควบคุมโรคแล้วประเมินผล (intervention และ evaluation) และสุดท้ายขยายผลมาตรการที่ได้ผลไปยังชุมชนอื่นที่บริบทคล้ายกัน (implementation และ scale up) ลำดับนี้ทำให้มาตรการที่ขยายออกไปตั้งอยู่บนปัญหาและปัจจัยเสี่ยงที่ยืนยันแล้ว ระบบเฝ้าระวังเองก็ต้องจบที่การลงมือ ถ้าเก็บและวิเคราะห์ข้อมูลแล้วไม่มี intervention ก็ไม่ใช่ระบบเฝ้าระวัง\n\n❌ ทำไมข้ออื่นผิด\n— ในกรอบนี้ investigation ตามมาหลังระบบเฝ้าระวังระบุปัญหาได้แล้ว จึงไม่ใช่งานแรก\n— การออกมาตรการก่อนสอบสวนทำให้มาตรการไม่ได้ตั้งอยู่บนปัจจัยเสี่ยงที่แท้จริง\n— การขยายผลต้องทำหลังมาตรการผ่านการประเมินแล้วว่าได้ผล ไม่ใช่ก่อนประเมิน\n— implementation คือการขยายผลมาตรการที่ได้ผลแล้ว จึงอยู่ท้ายสุด ไม่ใช่จุดเริ่มต้น\n\n💡 เห็นปัญหา สอบสวนหาเหตุ ออกมาตรการและประเมิน แล้วจึงขยายผล",
