    "q": "ในประชากรที่ไวรับเชื้อทั้งหมด (completely susceptible population) ผู้ป่วย 1 รายแพร่เชื้อต่อให้ได้เฉลี่ย 4 ราย ถ้านับผู้ป่วยรายแรกเป็น generation ที่ 1 ใน generation ที่ 3 จะมีผู้ติดเชื้อรายใหม่กี่ราย และค่า R0 นี้บ่งบอกสถานการณ์ใด",
