    "answer": 0,
    "explain": "R0 (basic reproductive number) คือจำนวนผู้ติดเชื้อรายใหม่โดยเฉลี่ยที่ผู้ป่วย 1 รายก่อขึ้นในประชากรที่ไวรับเชื้อทั้งหมด เมื่อ R0 เท่ากับ 4 จำนวนผู้ติดเชื้อรายใหม่ในแต่ละ generation จึงคูณ 4 ไปเรื่อย ๆ generation ที่ 1 มี 1 ราย generation ที่ 2 มี 4 ราย และ generation ที่ 3 มี 4 × 4 = 16 ราย ถ้านับสะสมทั้งสาม generation จะได้ 21 ราย การแปลผลคือ R0 น้อยกว่า 1 โรคถูกควบคุม (controlled) เท่ากับ 1 โรคคงตัวเป็น endemic และมากกว่า 1 เกิดการระบาด (epidemic) ถ้าไม่มี intervention เลย โรคติดต่อจะแพร่จนเกือบทุกคนในประชากรที่ยังไม่มีภูมิติดเชื้อ แล้วจำนวนผู้ป่วยจึงลดลงเมื่อผู้ป่วยหายและมีภูมิ หรือเสียชีวิต หลักนี้ใช้กับประชากรสัตว์ที่ไม่เคยพบเชื้อและไม่เคยได้วัคซีนมาก่อนได้เช่นกัน\n\n❌ ทำไมข้ออื่นผิด\n— 12 รายมาจากการบวกเพิ่มทีละ 4 แต่ผู้ป่วยใหม่ทุกรายแพร่ต่อได้อีกรายละ 4 ราย จำนวนจึงคูณ ไม่ใช่บวก\n— 16 รายถูกแล้ว แต่ endemic หมายถึง R0 เท่ากับ 1 คือผู้ป่วยแต่ละรายแพร่ต่อได้ 1 ราย จำนวนจึงคงตัว\n— 21 รายคือยอดสะสมของ generation ที่ 1 ถึง 3 ไม่ใช่ผู้ติดเชื้อรายใหม่ใน generation ที่ 3\n— 64 รายคือ 4 ยกกำลัง 3 ซึ่งเป็นผู้ติดเชื้อรายใหม่ของ generation ที่ 4 และ endemic ใช้กับ R0 เท่ากับ 1\n\n💡 generation ที่ n มีผู้ติดเชื้อรายใหม่เท่ากับ R0 ยกกำลัง (n − 1)",
