    "q": "โรคหัดมีค่า R0 สูงได้ถึงประมาณ 18 สัดส่วนของประชากรที่ต้องมีภูมิคุ้มกันเพื่อให้เกิดภูมิคุ้มกันหมู่ (herd immunity) คำนวณได้ประมาณเท่าใด",
