    "type": "mcq",
    "examScope": "midterm",
    "q": "การติดตามความครอบคลุมของการฉีดวัคซีนพิษสุนัขบ้าในสัตว์ เพื่อคาดการณ์ล่วงหน้าว่าจะพบหัวสุนัขให้ผลบวกและผู้ป่วยเพิ่มขึ้น จัดเป็นการเฝ้าระวังมิติใดใน 5-dimension surveillance",
    "options": [
      "Determinants",
      "Behavioral risks",
      "Measures",
      "Situation",
      "Events"
    ],
    "answer": 2,
    "explain": "5-dimension surveillance แบ่งสิ่งที่เฝ้าระวังเป็น 5 มิติ คือ determinants, behavioral risks, measures, situation และ events เดิมมักเฝ้าระวังเฉพาะตัวโรค ซึ่งเป็นผลลัพธ์ปลายทาง พอพบผู้ป่วยพิษสุนัขบ้าก็แปลว่ามีคนเสียชีวิตไปแล้ว จึงขยายไปเฝ้าระวังฝั่งเหตุด้วยเพื่อคาดการณ์ก่อนโรคเกิด มิติ measures คือระดับของมาตรการทางสาธารณสุขหรือทางปศุสัตว์ เมื่อมาตรการลดลง โรคมักเพิ่มขึ้นตามมา ความครอบคลุมวัคซีนในสัตว์ที่ลดลงจึงเตือนล่วงหน้าได้ว่าจะพบหัวบวกและผู้ป่วยมากขึ้น ไม่ว่าจะเฝ้าระวังมิติใด ระบบต้องจบที่ intervention ถ้าเก็บและวิเคราะห์ข้อมูลแล้วไม่ลงมือทำอะไร ก็ไม่ใช่ระบบเฝ้าระวัง\n\n❌ ทำไมข้ออื่นผิด\n— Determinants คือปัจจัยต้นเหตุที่เอื้อให้เกิดโรค เช่น รายได้และสภาพที่อยู่อาศัย ไม่ใช่ระดับของมาตรการ\n— Behavioral risks คือพฤติกรรมเสี่ยงของประชากร เช่น สัดส่วนคนที่ใส่หน้ากากในที่ชุมชนช่วง COVID-19\n— Situation คือสถานการณ์ของตัวโรค เช่น จำนวนหัวสุนัขที่ตรวจพบเชื้อ ซึ่งเป็นผลลัพธ์ที่เกิดแล้ว\n— Events คือเหตุการณ์ผิดปกติที่เกิดขึ้นแล้ว เช่น คลัสเตอร์ผู้ป่วยหรือสัตว์ตายผิดปกติ ซึ่งเป็นผลลัพธ์ปลายทางเช่นกัน\n\n💡 เฝ้าระวังเหตุ (determinants, behavior, measures) ก่อนต้องมานับผล (situation, events)",
    "source": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf หน้า 24",
    "sourceType": "lecture-derived",
    "verified": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf น.24 (หน้าเรื่อง 5-Dimension Surveillance: โน้ตเขียว แต่ก่อน surveillance แค่การเกิดโรค ตอนนี้ไปดู risk factor เพื่อ predict ว่าน่าจะมีโรคเกิดขึ้น, ใต้ Measures โน้ตแดง เฝ้าระวังมาตรการ เพราะถ้ามีการปรับเปลี่ยนมาตรการมักเกิดโรค และตัวอย่าง นโยบายของปศุสัตว์เรื่องการฉีด vac rabies ช่วงที่ปรับนโยบาย incidence เพิ่ม, ใต้ Behavioral Risks ตัวอย่างตอน Covid การที่คนไปร้านเหล้า, ใต้ Situation สมัยก่อนจะเฝ้าระวังโรคอย่างเดียว บางทีมันสายไปละ) และ น.23 (วงจร surveillance ถึง Intervention); ตรวจกับ _NpT5OMLkUk [72:38]-[74:05] (5 มิติ, measures ดรอปแล้วโรคเพิ่ม, เฝ้าระวังเฉพาะมิติ 4 เท่ากับมีคนตายแล้ว), [75:05]-[75:29] (ความครอบคลุมวัคซีนในสัตว์ดรอปแปลว่าจะเจอหัวบวกและคนป่วยมากขึ้น), [75:32]-[76:02] (ตัวอย่างการใส่หน้ากาก), [53:28]-[53:44] (รายได้และห้องแถวเป็น social determinants) และ [67:13] (ไม่มี intervention ไม่ใช่ระบบเฝ้าระวัง)",
