    "verified": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf น.16 (หน้า ประเด็นสำคัญจากการสอบสวน: โน้ตแดง ถ้าไม่หาสาเหตุของโรคจนเจอ prevent, control ผิด, เส้นใต้แดงที่ แต่มีไข้นานกว่า พร้อมโน้ต ปกติไข้เลือดออกจะไม่ไข้นาน, ไฮไลต์เขียวที่เห็บสีน้ำตาล Brown Dog Tick) น.7 (Leptospirosis, Rickettsia: neg และ Stiff neck เป็นบวกในตาราง, โน้ต เป็นไข้มา 9 วันละ ปกติไข้เลือดออกจะไม่นานขนาดนี้, เส้นใต้หยักแดงที่ Deng: weakly pos พร้อมโน้ต หมอเลยเข้าใจผิดคิดว่าเป็นไข้เลือดออก) น.10 (ไฮไลต์ นอนห้องเดียวกับสุนัข, เส้นใต้หยักแดงที่ เห็บกัดหลายครั้ง, กรอบแดงที่ เห็บเยอะเหมือนงาดำ, ไฮไลต์ สุนัขมีอาการซึม เบื่ออาหาร พร้อมโน้ต Hx ข้อนี้เลยให้ตรวจ SFTSV) และ น.14-15 (มาตรการคน สัตว์ สิ่งแวดล้อม ivermectin และ cypermethrin พร้อมโน้ต ต้องทำแบบ One Health ด้วย และ แยกเขาไว้ ที่ภาพกรงสุนัข); ตรวจกับ _NpT5OMLkUk [25:16]-[26:51] (ไข้ 9 วัน NS1 ลบ IgM บวกอ่อน), [27:24]-[27:43] และ [42:08]-[42:21] (ถ้าไม่สอบสวนจะไปจัดการลูกน้ำยุงลาย ทั้งที่โรคแพร่ด้วยเห็บ), [31:01]-[31:44] (นอนกับสุนัข เห็บกัด สุนัขซึม), [39:07]-[42:02] (มาตรการ 3 ด้าน) และ [43:40]-[43:48] (ถ้าไม่ได้หาสาเหตุจะควบคุมโรคผิดทาง); เห็บชนิดเดียวกับ 106058",
