    "q": "คลัสเตอร์แอนแทรกซ์ที่มุกดาหาร พ.ศ. 2568 มีผู้ป่วยยืนยัน 5 ราย โดย 2 รายไม่ได้ร่วมเชือดวัวและไม่ได้สัมผัสซากโดยตรง ทั้งสองรายน่าจะได้รับเชื้อทางใด",
