    "answer": 1,
    "explain": "การค้นหาผู้ป่วยพบ 5 ราย เชื่อมโยงกับวัวที่สงสัย 2 ตัวซึ่งถูกเชือดที่จุดเดียวกันในหมู่บ้านเดียวกัน วัวตัวแรกไม่มีประวัติตายผิดปกติ ส่วนตัวที่สองตายผิดปกติ ทั้ง 5 รายเป็นแอนแทรกซ์ทางผิวหนัง 3 รายสัมผัสซากโดยตรง อีก 2 รายสัมผัสอุปกรณ์ที่ปนเปื้อน รายหนึ่งถูกมีดเล่มที่ใช้ชำแหละวัวตัวแรกบาดนิ้วเมื่อนำไปชำแหละหมูในอีก 7 วันต่อมา อีกรายถูกมีดทำครัวที่ใช้หั่นเนื้อวัวตัวที่สองบาดนิ้วเมื่อนำไปเตรียมปลาในอีก 3 วันต่อมา สวอบมีดของ index case ดินบริเวณจุดเชือด และเนื้อวัวจากการเชือดวันที่ 28 เมษายน ตรวจพบ Bacillus anthracis ด้วย PCR ทั้ง 5 รายมีแผลเล็ก ๆ ที่มือซึ่งเป็นทางเข้าของเชื้อ ระยะฟักตัวมัธยฐาน 1 วัน การค้นหาผู้สัมผัสจึงต้องตามทั้งคนที่เชือดสัตว์ ตัวอุปกรณ์ และทุกคนที่ใช้อุปกรณ์นั้น แล้วทำลายอุปกรณ์ที่ปนเปื้อน เพราะสปอร์ทนในสิ่งแวดล้อมได้นาน\n\n❌ ทำไมข้ออื่นผิด\n— ผู้ป่วยทั้ง 5 รายเป็นแอนแทรกซ์ทางผิวหนัง ไม่มีรายใดเป็นแบบทางเดินอาหาร\n— ดินบริเวณจุดเชือดตรวจพบเชื้อจริง แต่ทั้งสองรายเป็นแบบผิวหนังจากแผลมีดบาด ไม่ใช่แบบทางหายใจ\n— แอนแทรกซ์ไม่ติดต่อจากคนสู่คน การดูแลผู้ป่วยจึงไม่ใช่ทางติดเชื้อ\n— แมลงดูดเลือดแพร่เชื้อทางกลได้ในสัตว์ แต่ทั้งสองรายมีประวัติมีดบาดนิ้วชัดเจน และสวอบมีดของ index case ตรวจพบเชื้อ\n\n💡 คลัสเตอร์นี้ มีดคือตัวกลางที่มองข้าม ต้องตามทั้งคนและอุปกรณ์",
    "source": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf หน้า 62",
    "sourceType": "lecture-derived",
    "verified": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf น.62 (หน้า Case Finding and Epidemiological Linkage: เส้นใต้หยักแดงที่ 5 cases พร้อมโน้ต เป็น Anthrax แผล, ไฮไลต์ The same kitchen knife was reused to prepare fish on May 1 พร้อมโน้ต เค้าเอามีดที่ใช้เชือดวัว Anthrax ไปใช้ แล้วมันบาดมือ, มีดวันที่ 12 เม.ย. ใช้ชำแหละหมู 19 เม.ย.) น.63 (ไฮไลต์ All 5 cases presented with cutaneous anthrax, exposure 3 direct contact, 2 contaminated equipment, incubation median 1 day, all had minor hand injuries) น.64 (โน้ต มีดที่ใช้เชือดก็เป็น fomite ให้แพร่โรคได้, Anthrax มันอยู่ในดินได้, เนื้อที่เชือดมาก็มีเชื้อ) น.59 (ไฮไลต์แดง not spread from person to person พร้อมโน้ต ไม่ติดจากคนสู่คน) และ น.66 (ไฮไลต์ Not only direct contact); ตรวจกับ _NpT5OMLkUk [148:27]-[149:48] (โซ่การติดต่อ 2 รายที่ไม่ได้เชือดวัวแต่ถูกมีดบาด), [150:16]-[150:20] (ทั้ง 5 รายเป็นแบบผิวหนัง), [151:46]-[152:07] (มีด ดิน เนื้อ ให้ผลบวก) และ [154:35]-[154:47] (อุปกรณ์เป็นบทเรียนที่เน้นที่สุด)",
