    "verified": "10 - lessons from the field_outbreak investigation of zoonotic diseases.pdf น.61 (ไทม์ไลน์ Apr 28 Blood Gram stain suggested anthrax ไฮไลต์ฟ้า, Apr 29 RT-PCR บวกและ sepsis, Apr 30 เสียชีวิต, โน้ตแดงหัวหน้า Q: ถ้าย้อนเวลากลับไปได้ ในฐานะ vet เราจะป้องกัน case นี้ยังไงบ้าง พร้อมภาพถ่ายกระดาษคำตอบลายมือของงานเขียนในคาบ ชื่อและรหัสบนกระดาษไม่ได้คัดลอก เนื้อหาคือ surveillance ในพื้นที่เสี่ยงเพื่อ early detect, ให้ความรู้ชุมชนเพื่อช่วย passive surveillance, คุมการเชือดสัตว์และ food safety แบบ One Health) น.65 (โน้ตแดง ประสานงานให้เร็ว, หาคนที่สัมผัสกับวัว รีบจ่าย ABO, ตรวจโรค ฉีด Vac, ต้องเริ่มคุมและกักกัน จ่าย ABO, ต้องห้ามเคลื่อนย้าย, จริงๆ มันก็ฆ่าไม่หมด สปอร์ทนมาก ถ้าจะฝังดินต้องฝังลึกมากๆ ไม่งั้นมีสัตว์ไปขุด เกิดโรคใหม่, อุปกรณ์เสี่ยงต่างๆ เอาไปฝังซะ) และ น.66 (ไฮไลต์ EOC พร้อมโน้ต รีบประสานงาน, collaboration, risk communication, Not only direct contact); ตรวจกับ _NpT5OMLkUk [155:00]-[158:51] (โจทย์เขียนตอบในคาบ ในฐานะสัตวแพทย์หรือปศุสัตว์จังหวัด), [173:45]-[175:12] (เฉลยสามประเด็น active surveillance ในสัตว์ [174:05], อุปกรณ์ [174:10]-[174:35], เครือข่ายกับชุมชนและอาสาสมัคร [174:38]-[175:12]), [152:07]-[154:13] (มาตรการคน สัตว์ สิ่งแวดล้อม วัคซีนรัศมี 5 กม. [152:47] กักกัน 124 ตัว 20 วัน [152:58] จุดป้องกันการค้าสัตว์ผิดกฎหมาย), [151:03]-[151:46] (หามีดใหม่ไปแลกแล้วฝังกลบ), [153:17]-[153:44] (สปอร์ ฝังไม่ลึกสัตว์คุ้ยขึ้นมา); ห้ามผ่าซากตรงกับ 106029",
